import hashlib
import hmac
import ipaddress
import json
import os
import socket
from html.parser import HTMLParser
from urllib.parse import urlparse

import requests
from fastapi import APIRouter, Depends, Header, HTTPException, Query, Request
from sqlalchemy.orm import Session

from app.db import get_db
from app.models import Order

router = APIRouter()

PAID_EVENTS = {"payment.succeeded"}
FAILED_EVENTS = {"payment.failed"}

MAX_PREVIEW_BYTES = 300_000


@router.post("/webhooks/payments")
async def payments_webhook(
    request: Request,
    x_signature: str = Header(..., alias="X-Signature"),
    db: Session = Depends(get_db),
) -> dict[str, object]:
    secret = os.environ.get("PAYMENTS_WEBHOOK_SECRET")
    if not secret:
        raise HTTPException(status_code=500, detail="webhook secret not configured")

    body = await request.body()
    expected_signature = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_signature, x_signature):
        raise HTTPException(status_code=401, detail="invalid signature")

    try:
        payload = json.loads(body)
    except json.JSONDecodeError as exc:
        raise HTTPException(status_code=400, detail="invalid JSON body") from exc

    event = payload.get("event")
    order_id = payload.get("order_id")
    payment_id = payload.get("payment_id")

    if event not in PAID_EVENTS | FAILED_EVENTS or order_id is None:
        raise HTTPException(status_code=400, detail="invalid payload")

    order = db.get(Order, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")

    order.status = "paid" if event in PAID_EVENTS else "failed"
    if payment_id:
        order.payment_id = payment_id
    db.commit()

    return {"id": order.id, "status": order.status}


class _PreviewParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.title: str | None = None
        self.description: str | None = None
        self._in_title = False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attrs_dict = dict(attrs)
        if tag == "title":
            self._in_title = True
        elif tag == "meta":
            name = (attrs_dict.get("name") or attrs_dict.get("property") or "").lower()
            if name in ("description", "og:description") and self.description is None:
                self.description = attrs_dict.get("content")

    def handle_endtag(self, tag: str) -> None:
        if tag == "title":
            self._in_title = False

    def handle_data(self, data: str) -> None:
        if self._in_title and self.title is None:
            self.title = data.strip()


def _is_public_ip(ip_str: str) -> bool:
    ip = ipaddress.ip_address(ip_str)
    return not (
        ip.is_private
        or ip.is_loopback
        or ip.is_link_local
        or ip.is_multicast
        or ip.is_reserved
        or ip.is_unspecified
    )


def _assert_safe_url(url: str) -> None:
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise HTTPException(status_code=400, detail="url must use http or https")
    if not parsed.hostname:
        raise HTTPException(status_code=400, detail="invalid url")

    try:
        resolved = socket.getaddrinfo(parsed.hostname, None)
    except socket.gaierror as exc:
        raise HTTPException(status_code=400, detail="could not resolve host") from exc

    for family, _type, _proto, _canonname, sockaddr in resolved:
        if family not in (socket.AF_INET, socket.AF_INET6):
            continue
        if not _is_public_ip(sockaddr[0]):
            raise HTTPException(status_code=400, detail="url resolves to a disallowed address")


@router.get("/link-preview")
def link_preview(url: str = Query(...)) -> dict[str, str | None]:
    _assert_safe_url(url)

    try:
        resp = requests.get(
            url,
            timeout=5,
            allow_redirects=False,
            stream=True,
            headers={"User-Agent": "LinkPreviewBot/1.0"},
        )
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail="failed to fetch url") from exc

    if resp.status_code != 200:
        raise HTTPException(status_code=502, detail="failed to fetch url")

    content_type = resp.headers.get("Content-Type", "")
    if "text/html" not in content_type:
        raise HTTPException(status_code=400, detail="url did not return an HTML page")

    raw = resp.raw.read(MAX_PREVIEW_BYTES, decode_content=True)
    html_text = raw.decode(resp.encoding or "utf-8", errors="replace")

    parser = _PreviewParser()
    parser.feed(html_text)

    return {"title": parser.title, "description": parser.description}

from fastapi.testclient import TestClient

import app.routes.integrations as integrations
from app.main import app

client = TestClient(app)


class _FakeRaw:
    def __init__(self, data: bytes) -> None:
        self._data = data

    def read(self, n: int, decode_content: bool = True) -> bytes:
        return self._data[:n]


class _FakeResponse:
    def __init__(self, status_code: int, headers: dict, data: bytes) -> None:
        self.status_code = status_code
        self.headers = headers
        self.raw = _FakeRaw(data)
        self.encoding = "utf-8"


def test_link_preview_returns_title_and_description(monkeypatch):
    monkeypatch.setattr(
        integrations.socket, "getaddrinfo", lambda *a, **k: [(2, 1, 6, "", ("93.184.216.34", 0))]
    )
    html = (
        b"<html><head><title>Example Page</title>"
        b'<meta name="description" content="An example page"></head></html>'
    )

    def fake_get(url, **kwargs):
        return _FakeResponse(200, {"Content-Type": "text/html; charset=utf-8"}, html)

    monkeypatch.setattr(integrations.requests, "get", fake_get)

    resp = client.get("/link-preview", params={"url": "http://example.com/"})

    assert resp.status_code == 200
    assert resp.json() == {"title": "Example Page", "description": "An example page"}


def test_link_preview_rejects_non_html_content(monkeypatch):
    monkeypatch.setattr(
        integrations.socket, "getaddrinfo", lambda *a, **k: [(2, 1, 6, "", ("93.184.216.34", 0))]
    )
    monkeypatch.setattr(
        integrations.requests, "get", lambda url, **k: _FakeResponse(200, {"Content-Type": "application/json"}, b"{}")
    )

    resp = client.get("/link-preview", params={"url": "http://example.com/data.json"})

    assert resp.status_code == 400


def test_link_preview_rejects_loopback_address():
    resp = client.get("/link-preview", params={"url": "http://127.0.0.1/admin"})

    assert resp.status_code == 400


def test_link_preview_rejects_cloud_metadata_address():
    resp = client.get("/link-preview", params={"url": "http://169.254.169.254/latest/meta-data/"})

    assert resp.status_code == 400


def test_link_preview_rejects_non_http_scheme():
    resp = client.get("/link-preview", params={"url": "file:///etc/passwd"})

    assert resp.status_code == 400

