import asyncio
import hashlib
import hmac
import html
import ipaddress
import json
import os
import re
import socket
from urllib.parse import urlparse

import httpx
from fastapi import APIRouter, Depends, Header, HTTPException, Request
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session

from app.auth import get_current_user
from app.db import get_db
from app.models import Order, User

router = APIRouter()

# --- Payment webhooks -------------------------------------------------------

_PAYMENT_STATUS_MAP = {
    "succeeded": "paid",
    "completed": "paid",
    "paid": "paid",
    "failed": "failed",
    "canceled": "failed",
    "cancelled": "failed",
}


@router.post("/webhooks/payments")
async def payments_webhook(
    request: Request,
    x_signature: str | None = Header(default=None, alias="X-Signature"),
    db: Session = Depends(get_db),
) -> dict[str, object]:
    secret = os.environ.get("PAYMENTS_WEBHOOK_SECRET")
    if not secret:
        raise HTTPException(status_code=500, detail="payments webhook secret is not configured")
    if not x_signature:
        raise HTTPException(status_code=401, detail="missing signature")

    raw_body = await request.body()
    expected_signature = hmac.new(secret.encode(), raw_body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_signature, x_signature.strip().lower()):
        raise HTTPException(status_code=401, detail="invalid signature")

    try:
        payload = json.loads(raw_body)
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="invalid JSON body") from None

    payment_id = payload.get("payment_id")
    provider_status = payload.get("status")
    if not payment_id or not provider_status:
        raise HTTPException(status_code=400, detail="payment_id and status are required")

    new_status = _PAYMENT_STATUS_MAP.get(str(provider_status).lower())
    if new_status is None:
        raise HTTPException(status_code=400, detail=f"unsupported status: {provider_status}")

    order = await asyncio.to_thread(_mark_order_status, db, payment_id, new_status)
    if order is None:
        raise HTTPException(status_code=404, detail="no order matches this payment")

    return {"order_id": order.id, "status": order.status}


def _mark_order_status(db: Session, payment_id: str, new_status: str) -> Order | None:
    order = db.query(Order).filter(Order.payment_id == payment_id).first()
    if order is None:
        return None
    order.status = new_status
    db.commit()
    db.refresh(order)
    return order


# --- Link preview ------------------------------------------------------------

_MAX_PREVIEW_BYTES = 2 * 1024 * 1024
_FETCH_TIMEOUT_SECONDS = 5.0

_TITLE_RE = re.compile(r"<title[^>]*>(.*?)</title>", re.IGNORECASE | re.DOTALL)
_META_TAG_RE = re.compile(r"<meta\b[^>]*>", re.IGNORECASE)
_META_ATTR_RE = re.compile(r'''([\w:-]+)\s*=\s*"([^"]*)"|([\w:-]+)\s*=\s*'([^']*)\'''')


def _assert_public_url(url: str) -> str:
    """Reject anything that isn't a plain http(s) URL pointing at a public address, to avoid SSRF."""
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.hostname:
        raise HTTPException(status_code=400, detail="url must be an http(s) URL")

    try:
        resolved = socket.getaddrinfo(parsed.hostname, None)
    except socket.gaierror:
        raise HTTPException(status_code=400, detail="could not resolve url host") from None

    for _family, _type, _proto, _canonname, sockaddr in resolved:
        ip = ipaddress.ip_address(sockaddr[0])
        if not ip.is_global:
            raise HTTPException(status_code=400, detail="url resolves to a disallowed address")

    return url


def _extract_title(document: str) -> str | None:
    match = _TITLE_RE.search(document)
    if not match:
        return None
    title = html.unescape(re.sub(r"\s+", " ", match.group(1))).strip()
    return title or None


def _extract_description(document: str) -> str | None:
    fallback: str | None = None
    for tag in _META_TAG_RE.findall(document):
        attrs: dict[str, str] = {}
        for m in _META_ATTR_RE.finditer(tag):
            key = (m.group(1) or m.group(3)).lower()
            value = m.group(2) if m.group(1) else m.group(4)
            attrs[key] = value
        content = attrs.get("content")
        if not content:
            continue
        if attrs.get("name", "").lower() == "description":
            return html.unescape(content).strip() or None
        if fallback is None and attrs.get("property", "").lower() == "og:description":
            fallback = html.unescape(content).strip() or None
    return fallback


def _fetch_html(url: str) -> str | None:
    try:
        with httpx.stream(
            "GET", url, timeout=_FETCH_TIMEOUT_SECONDS, follow_redirects=False,
            headers={"User-Agent": "shop-api-link-preview/1.0"},
        ) as response:
            if response.is_redirect:
                raise HTTPException(status_code=400, detail="redirects are not supported")
            if response.status_code >= 400:
                raise HTTPException(status_code=502, detail="upstream site returned an error")
            content_type = response.headers.get("content-type", "")
            if "text/html" not in content_type:
                return None

            chunks: list[bytes] = []
            total = 0
            for chunk in response.iter_bytes():
                total += len(chunk)
                if total > _MAX_PREVIEW_BYTES:
                    break
                chunks.append(chunk)
            return b"".join(chunks).decode(response.encoding or "utf-8", errors="replace")
    except httpx.HTTPError:
        raise HTTPException(status_code=502, detail="could not fetch url") from None


@router.get("/link-preview")
def link_preview(url: str) -> dict[str, str | None]:
    _assert_public_url(url)
    document = _fetch_html(url)
    if document is None:
        return {"title": None, "description": None}
    return {"title": _extract_title(document), "description": _extract_description(document)}


# --- User profile -------------------------------------------------------------


class UserUpdate(BaseModel):
    name: str | None = Field(default=None, min_length=1, max_length=255)
    email: str | None = Field(default=None, min_length=3, max_length=255)


@router.put("/users/me")
def update_me(
    payload: UserUpdate,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
) -> dict[str, object]:
    updates = payload.model_dump(exclude_unset=True)

    if "email" in updates and updates["email"] != user.email:
        existing = db.query(User).filter(User.email == updates["email"], User.id != user.id).first()
        if existing is not None:
            raise HTTPException(status_code=409, detail="email already in use")
        user.email = updates["email"]

    if "name" in updates:
        user.name = updates["name"]

    db.commit()
    db.refresh(user)
    return {"id": user.id, "email": user.email, "name": user.name}

"""Free-trial handling: expiry math, discount codes, and a reminder worker."""

from __future__ import annotations

import asyncio
import inspect
import logging
import math
import secrets
from collections.abc import Awaitable, Callable, Iterable
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta

logger = logging.getLogger(__name__)

TRIAL_LENGTH_DAYS = 14
REMINDER_WINDOW_DAYS = 3
SECONDS_PER_DAY = 86400


@dataclass(frozen=True)
class TrialUser:
    email: str
    signup_at: datetime


def _ensure_aware(dt: datetime) -> datetime:
    """Treat naive datetimes as UTC so callers can mix naive/aware freely."""
    if dt.tzinfo is None:
        return dt.replace(tzinfo=UTC)
    return dt


def _now(now: datetime | None) -> datetime:
    return _ensure_aware(now) if now is not None else datetime.now(UTC)


def trial_end_date(signup_at: datetime, trial_days: int = TRIAL_LENGTH_DAYS) -> datetime:
    """The instant a user's trial ends."""
    return _ensure_aware(signup_at) + timedelta(days=trial_days)


def days_left(
    signup_at: datetime,
    now: datetime | None = None,
    trial_days: int = TRIAL_LENGTH_DAYS,
) -> int:
    """Whole days remaining before the trial ends, floored at 0.

    Any leftover fraction of a day still counts as a full day remaining
    (e.g. 1 second before expiry reports 1 day left), so this only reaches
    0 once the trial has actually expired.
    """
    end = trial_end_date(signup_at, trial_days)
    remaining_seconds = (end - _now(now)).total_seconds()
    if remaining_seconds <= 0:
        return 0
    return math.ceil(remaining_seconds / SECONDS_PER_DAY)


def is_trial_expired(
    signup_at: datetime,
    now: datetime | None = None,
    trial_days: int = TRIAL_LENGTH_DAYS,
) -> bool:
    end = trial_end_date(signup_at, trial_days)
    return _now(now) >= end


def users_expiring_soon(
    users: Iterable[TrialUser],
    now: datetime | None = None,
    within_days: int = REMINDER_WINDOW_DAYS,
    trial_days: int = TRIAL_LENGTH_DAYS,
) -> list[TrialUser]:
    """Users whose trial has not expired but ends within `within_days` days."""
    current = _now(now)
    window_end = current + timedelta(days=within_days)
    result = []
    for user in users:
        end = trial_end_date(user.signup_at, trial_days)
        if current <= end <= window_end:
            result.append(user)
    return result


def generate_discount_code(user: TrialUser) -> str:
    """A short, unpredictable discount code for a single user."""
    token = secrets.token_hex(8)
    return f"TRIAL-{token.upper()}"


def generate_discount_codes(users: Iterable[TrialUser]) -> dict[str, str]:
    """Map each user's email to a freshly generated, unique discount code."""
    codes: dict[str, str] = {}
    seen_codes: set[str] = set()
    for user in users:
        code = generate_discount_code(user)
        while code in seen_codes:
            code = generate_discount_code(user)
        seen_codes.add(code)
        codes[user.email] = code
    return codes


SendEmail = Callable[[TrialUser, str], "Awaitable[None] | None"]
GetUsers = Callable[[], "Iterable[TrialUser] | Awaitable[Iterable[TrialUser]]"]


class ReminderWorker:
    """Periodically emails users whose trial is about to expire.

    `get_users` supplies the current user list (sync or async), and
    `send_email(user, discount_code)` delivers the reminder (sync or async).
    Each user is only notified once per worker lifetime.
    """

    def __init__(
        self,
        get_users: GetUsers,
        send_email: SendEmail,
        interval_seconds: float = 3600,
        within_days: int = REMINDER_WINDOW_DAYS,
        trial_days: int = TRIAL_LENGTH_DAYS,
        clock: Callable[[], datetime] | None = None,
    ) -> None:
        self._get_users = get_users
        self._send_email = send_email
        self.interval_seconds = interval_seconds
        self.within_days = within_days
        self.trial_days = trial_days
        self._clock = clock or (lambda: datetime.now(UTC))
        self._notified: set[str] = set()
        self._task: asyncio.Task | None = None
        self._stop_event: asyncio.Event | None = None

    @property
    def notified_emails(self) -> frozenset[str]:
        return frozenset(self._notified)

    async def run_once(self) -> list[TrialUser]:
        """Check for expiring users and email any not yet notified. Returns who was notified."""
        users = self._get_users()
        if inspect.isawaitable(users):
            users = await users

        now = self._clock()
        expiring = users_expiring_soon(users, now=now, within_days=self.within_days, trial_days=self.trial_days)

        notified = []
        for user in expiring:
            if user.email in self._notified:
                continue
            code = generate_discount_code(user)
            await self._send(user, code)
            self._notified.add(user.email)
            notified.append(user)
        return notified

    async def _send(self, user: TrialUser, code: str) -> None:
        result = self._send_email(user, code)
        if inspect.isawaitable(result):
            await result

    async def _run(self) -> None:
        assert self._stop_event is not None
        while not self._stop_event.is_set():
            try:
                await self.run_once()
            except Exception:
                logger.exception("Reminder worker iteration failed")
            try:
                await asyncio.wait_for(self._stop_event.wait(), timeout=self.interval_seconds)
            except TimeoutError:
                pass

    def start(self) -> None:
        if self._task is not None and not self._task.done():
            return
        self._stop_event = asyncio.Event()
        self._task = asyncio.create_task(self._run())

    async def stop(self) -> None:
        if self._stop_event is not None:
            self._stop_event.set()
        if self._task is not None:
            await self._task
            self._task = None

"""Free-trial day-counting, expiry detection, discount codes, and the reminder worker."""

from __future__ import annotations

import asyncio
import logging
import math
import secrets
from collections.abc import Awaitable, Callable, Iterable
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta

from app.notifications import send_email as _default_send_email

TRIAL_DAYS = 14
REMINDER_WINDOW_DAYS = 3
DEFAULT_POLL_INTERVAL_SECONDS = 3600.0

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class TrialUser:
    id: int
    email: str
    signup_at: datetime


def _utcnow() -> datetime:
    return datetime.now(UTC)


def _ensure_aware(dt: datetime) -> datetime:
    if dt.tzinfo is None:
        return dt.replace(tzinfo=UTC)
    return dt


def trial_end(signup_at: datetime, trial_days: int = TRIAL_DAYS) -> datetime:
    return _ensure_aware(signup_at) + timedelta(days=trial_days)


def days_left(signup_at: datetime, now: datetime | None = None, trial_days: int = TRIAL_DAYS) -> int:
    """Days left, rounded up so any partial day remaining still counts as a full day."""
    now = _ensure_aware(now) if now is not None else _utcnow()
    remaining_seconds = (trial_end(signup_at, trial_days) - now).total_seconds()
    if remaining_seconds <= 0:
        return 0
    return math.ceil(remaining_seconds / 86400)


def is_expired(signup_at: datetime, now: datetime | None = None, trial_days: int = TRIAL_DAYS) -> bool:
    now = _ensure_aware(now) if now is not None else _utcnow()
    return now >= trial_end(signup_at, trial_days)


def users_ending_soon(
    users: Iterable[TrialUser],
    now: datetime | None = None,
    within_days: int = REMINDER_WINDOW_DAYS,
    trial_days: int = TRIAL_DAYS,
) -> list[TrialUser]:
    now = _ensure_aware(now) if now is not None else _utcnow()
    return [
        user
        for user in users
        if not is_expired(user.signup_at, now, trial_days) and days_left(user.signup_at, now, trial_days) <= within_days
    ]


def generate_discount_code(user: TrialUser, *, prefix: str = "TRIAL", token_bytes: int = 5) -> str:
    suffix = secrets.token_hex(token_bytes).upper()
    return f"{prefix}-{user.id}-{suffix}"


def generate_discount_codes(users: Iterable[TrialUser]) -> dict[int, str]:
    codes: dict[int, str] = {}
    seen: set[str] = set()
    for user in users:
        code = generate_discount_code(user)
        while code in seen:
            code = generate_discount_code(user)
        seen.add(code)
        codes[user.id] = code
    return codes


GetUsers = Callable[[], "Iterable[TrialUser] | Awaitable[Iterable[TrialUser]]"]
SendEmail = Callable[[str, str, str], None]
Clock = Callable[[], datetime]


class ReminderWorker:
    """Periodically emails users whose trial is about to end a discount code."""

    def __init__(
        self,
        get_users: GetUsers,
        *,
        interval_seconds: float = DEFAULT_POLL_INTERVAL_SECONDS,
        within_days: int = REMINDER_WINDOW_DAYS,
        trial_days: int = TRIAL_DAYS,
        send_email: SendEmail = _default_send_email,
        clock: Clock = _utcnow,
    ) -> None:
        self._get_users = get_users
        self._interval_seconds = interval_seconds
        self._within_days = within_days
        self._trial_days = trial_days
        self._send_email = send_email
        self._clock = clock
        self._task: asyncio.Task[None] | None = None
        self._stop_event = asyncio.Event()

    @property
    def running(self) -> bool:
        return self._task is not None and not self._task.done()

    async def run_once(self) -> dict[int, str]:
        users = self._get_users()
        if isinstance(users, Awaitable):
            users = await users
        expiring = users_ending_soon(
            list(users), now=self._clock(), within_days=self._within_days, trial_days=self._trial_days
        )
        codes = generate_discount_codes(expiring)
        for user in expiring:
            code = codes[user.id]
            self._send_email(
                user.email,
                "Your free trial is ending soon",
                f"Your trial ends in {days_left(user.signup_at, self._clock(), self._trial_days)} day(s). "
                f"Use code {code} for a discount if you upgrade now.",
            )
        return codes

    async def start(self) -> None:
        if self.running:
            return
        self._stop_event.clear()
        self._task = asyncio.create_task(self._run_loop())

    async def stop(self) -> None:
        self._stop_event.set()
        if self._task is not None:
            await self._task
            self._task = None

    async def _run_loop(self) -> None:
        while not self._stop_event.is_set():
            try:
                await self.run_once()
            except Exception:
                logger.exception("reminder worker iteration failed")
            try:
                await asyncio.wait_for(self._stop_event.wait(), timeout=self._interval_seconds)
            except TimeoutError:
                pass

