package com.acme.app.feed

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.acme.app.data.FeedRepository
import com.acme.app.data.Post
import java.io.File
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

data class FeedUiState(
    val posts: List<Post> = emptyList(),
    val isLoading: Boolean = false,
    val error: String? = null,
    val draft: String = "",
)

@Serializable
private data class DraftContent(val text: String)

class FeedViewModel(
    private val repository: FeedRepository,
    private val cacheDir: File,
    private val ioDispatcher: CoroutineDispatcher = Dispatchers.IO,
) : ViewModel() {

    private val draftFile: File
        get() = File(cacheDir, "feed_draft.json")

    private val _uiState = MutableStateFlow(FeedUiState(draft = loadDraft()))
    val uiState: StateFlow<FeedUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            repository.feed().collect { posts ->
                _uiState.update { it.copy(posts = posts) }
            }
        }
        refresh()
    }

    fun refresh() {
        if (_uiState.value.isLoading) return
        _uiState.update { it.copy(isLoading = true, error = null) }
        viewModelScope.launch {
            try {
                repository.refresh()
            } catch (e: Exception) {
                _uiState.update { it.copy(error = e.message ?: "Failed to refresh") }
            } finally {
                _uiState.update { it.copy(isLoading = false) }
            }
        }
    }

    fun toggleLike(postId: String) {
        val original = _uiState.value.posts.find { it.id == postId } ?: return
        val optimistic = original.copy(
            likedByMe = !original.likedByMe,
            likeCount = original.likeCount + if (original.likedByMe) -1 else 1,
        )
        _uiState.update { state -> state.replacing(postId, optimistic) }
        viewModelScope.launch {
            try {
                repository.setLiked(postId, optimistic.likedByMe)
            } catch (e: Exception) {
                _uiState.update { state ->
                    state.replacing(postId, original).copy(error = e.message ?: "Failed to update like")
                }
            }
        }
    }

    fun updateDraft(text: String) {
        _uiState.update { it.copy(draft = text) }
        viewModelScope.launch(ioDispatcher) {
            saveDraft(text)
        }
    }

    private fun FeedUiState.replacing(postId: String, replacement: Post): FeedUiState =
        copy(posts = posts.map { if (it.id == postId) replacement else it })

    private fun loadDraft(): String = try {
        if (draftFile.exists()) {
            Json.decodeFromString(DraftContent.serializer(), draftFile.readText()).text
        } else {
            ""
        }
    } catch (e: Exception) {
        ""
    }

    private fun saveDraft(text: String) {
        try {
            cacheDir.mkdirs()
            draftFile.writeText(Json.encodeToString(DraftContent.serializer(), DraftContent(text)))
        } catch (e: Exception) {
            // Draft persistence is best-effort; the in-memory draft remains authoritative for this session.
        }
    }
}

package com.acme.app.feed

import com.acme.app.data.FeedRepository
import com.acme.app.data.Post
import java.io.File
import java.nio.file.Files
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNull
import kotlin.test.assertTrue
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.flow.Flow
