import kotlinx.coroutines.test.resetMain
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.test.setMain

private class FakeFeedRepository(initialPosts: List<Post> = emptyList()) : FeedRepository {
    val feedFlow = MutableStateFlow(initialPosts)
    var refreshError: Throwable? = null
    var setLikedError: Throwable? = null
    var refreshCallCount = 0
        private set
    val setLikedCalls = mutableListOf<Pair<String, Boolean>>()

    override fun feed(): Flow<List<Post>> = feedFlow

    override suspend fun refresh() {
        refreshCallCount++
        refreshError?.let { throw it }
    }

    override suspend fun setLiked(postId: String, liked: Boolean) {
        setLikedCalls.add(postId to liked)
        setLikedError?.let { throw it }
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
class FeedViewModelTest {

    private val dispatcher = StandardTestDispatcher()
    private lateinit var cacheDir: File

    @BeforeTest
    fun setUp() {
        Dispatchers.setMain(dispatcher)
        cacheDir = Files.createTempDirectory("feed-vm-test").toFile()
    }

    @AfterTest
    fun tearDown() {
        cacheDir.deleteRecursively()
        Dispatchers.resetMain()
    }

    private fun samplePosts() = listOf(
        Post("p1", "Ada", "hello", likeCount = 2, likedByMe = false),
        Post("p2", "Grace", "world", likeCount = 5, likedByMe = true),
    )

    @Test
    fun initialLoad_collectsFeedAndRefreshes() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)

        advanceUntilIdle()

        assertEquals(samplePosts(), viewModel.uiState.value.posts)
        assertEquals(1, repo.refreshCallCount)
        assertFalse(viewModel.uiState.value.isLoading)
        assertNull(viewModel.uiState.value.error)
    }

    @Test
    fun refresh_setsLoadingWhileInFlightThenClearsIt() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.refresh()
        assertTrue(viewModel.uiState.value.isLoading)

        advanceUntilIdle()
        assertFalse(viewModel.uiState.value.isLoading)
        assertEquals(2, repo.refreshCallCount)
    }

    @Test
    fun refresh_failureSurfacesErrorAndClearsLoading() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        repo.refreshError = RuntimeException("network down")
        viewModel.refresh()
        advanceUntilIdle()

        assertFalse(viewModel.uiState.value.isLoading)
        assertEquals("network down", viewModel.uiState.value.error)
    }

    @Test
    fun toggleLike_updatesOptimisticallyBeforeRepositoryResolves() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p1")

        val optimistic = viewModel.uiState.value.posts.first { it.id == "p1" }
        assertTrue(optimistic.likedByMe)
        assertEquals(3, optimistic.likeCount)
    }

    @Test
    fun toggleLike_keepsOptimisticStateWhenRepositorySucceeds() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p1")
        advanceUntilIdle()

        val updated = viewModel.uiState.value.posts.first { it.id == "p1" }
        assertTrue(updated.likedByMe)
        assertEquals(3, updated.likeCount)
        assertEquals(listOf("p1" to true), repo.setLikedCalls)
        assertNull(viewModel.uiState.value.error)
    }

    @Test
    fun toggleLike_rollsBackWhenRepositoryFails() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        repo.setLikedError = RuntimeException("server rejected like")
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p1")
        advanceUntilIdle()

        val reverted = viewModel.uiState.value.posts.first { it.id == "p1" }
        assertFalse(reverted.likedByMe)
        assertEquals(2, reverted.likeCount)
        assertEquals("server rejected like", viewModel.uiState.value.error)
    }

    @Test
    fun toggleLike_unlikingDecrementsCount() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p2")

        val optimistic = viewModel.uiState.value.posts.first { it.id == "p2" }
        assertFalse(optimistic.likedByMe)
        assertEquals(4, optimistic.likeCount)
    }

    @Test
    fun draft_isPersistedToCacheDirAndRestoredByNewViewModel() = runTest(dispatcher) {
        val repo = FakeFeedRepository(samplePosts())
        val viewModel = FeedViewModel(repo, cacheDir, ioDispatcher = dispatcher)
        advanceUntilIdle()

        viewModel.updateDraft("draft in progress")
        assertEquals("draft in progress", viewModel.uiState.value.draft)

        advanceUntilIdle()
        assertTrue(File(cacheDir, "feed_draft.json").exists())

        val restored = FeedViewModel(FakeFeedRepository(), cacheDir, ioDispatcher = dispatcher)
        assertEquals("draft in progress", restored.uiState.value.draft)
    }

    @Test
    fun draft_missingFileYieldsEmptyDraft() = runTest(dispatcher) {
        val viewModel = FeedViewModel(FakeFeedRepository(), cacheDir, ioDispatcher = dispatcher)
        assertEquals("", viewModel.uiState.value.draft)
    }

    @Test
    fun draft_corruptFileYieldsEmptyDraftInsteadOfCrashing() = runTest(dispatcher) {
        cacheDir.mkdirs()
        File(cacheDir, "feed_draft.json").writeText("not valid json")

        val viewModel = FeedViewModel(FakeFeedRepository(), cacheDir, ioDispatcher = dispatcher)
        assertEquals("", viewModel.uiState.value.draft)
    }
}

