package com.acme.app.sync

import com.acme.app.data.Account
import com.acme.app.data.AccountApi
import java.io.File
import java.time.Instant
import kotlin.time.Duration
import kotlin.time.Duration.Companion.minutes
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

/** Progress of an in-flight [SyncManager.sync] run. */
data class SyncProgress(
    val accountsDone: Int,
    val accountsTotal: Int,
    val currentAccount: Account?,
)

/** Outcome of the most recently completed sync, for the UI to observe. */
data class SyncStatus(
    val lastSyncTime: Instant? = null,
    val lastError: String? = null,
)

/** Observable store of the last sync outcome. */
class SyncStatusStore {
    private val _status = MutableStateFlow(SyncStatus())
    val status: StateFlow<SyncStatus> = _status.asStateFlow()

    fun recordSuccess(time: Instant) {
        _status.value = SyncStatus(lastSyncTime = time, lastError = null)
    }

    fun recordError(message: String) {
        _status.value = _status.value.copy(lastError = message)
    }
}

@Serializable
private data class CursorFileContents(val cursors: Map<String, String> = emptyMap())

/** Persists each account's last-seen cursor to a local JSON file so syncs can resume. */
class CursorStore(private val file: File) {
    private val json = Json { ignoreUnknownKeys = true }

    @Synchronized
    fun load(): Map<String, String> {
        if (!file.exists()) return emptyMap()
        return runCatching { json.decodeFromString<CursorFileContents>(file.readText()).cursors }
            .getOrDefault(emptyMap())
    }

    @Synchronized
    fun save(cursors: Map<String, String>) {
        file.parentFile?.mkdirs()
        file.writeText(json.encodeToString(CursorFileContents(cursors)))
    }
}

/**
 * Syncs every account by paging through [AccountApi.changesSince] until there's no next cursor,
 * resuming each account from its last persisted cursor.
 */
class SyncManager(
    private val accountApi: AccountApi,
    private val cursorStore: CursorStore,
    private val statusStore: SyncStatusStore,
    private val now: () -> Instant = Instant::now,
) {
    /** Runs one full sync of all accounts, emitting progress as each account completes. */
    fun sync(): Flow<SyncProgress> = flow {
        val cursors = cursorStore.load().toMutableMap()
        try {
            val accounts = accountApi.accounts()
            emit(SyncProgress(accountsDone = 0, accountsTotal = accounts.size, currentAccount = null))
            accounts.forEachIndexed { index, account ->
                syncAccount(account, cursors)
                emit(SyncProgress(accountsDone = index + 1, accountsTotal = accounts.size, currentAccount = account))
            }
            statusStore.recordSuccess(now())
        } catch (e: Exception) {
            statusStore.recordError(e.message ?: e.toString())
            throw e
        }
    }

    private suspend fun syncAccount(account: Account, cursors: MutableMap<String, String>) {
        var cursor = cursors[account.id]
        while (true) {
            val page = accountApi.changesSince(account.id, cursor)
            val nextCursor = page.nextCursor ?: break
            cursor = nextCursor
            cursors[account.id] = cursor
            cursorStore.save(cursors)
        }
    }

    /** Starts syncing immediately and then every [interval], until the returned [Job] is cancelled. */
    fun startPeriodicSync(scope: CoroutineScope, interval: Duration = 15.minutes): Job =
        scope.launch {
            while (isActive) {
                runCatching { sync().collect {} }
                delay(interval)
            }
        }
}

