private class FakeAccountApi(
    private val accountsList: List<Account>,
    private val pages: Map<String, List<ChangePage>>,
) : AccountApi {
    val calls = mutableListOf<Pair<String, String?>>()
    var accountsCallCount = 0
        private set
    var failNextChangesSince: Exception? = null

    private val callIndex = mutableMapOf<String, Int>()

    override suspend fun accounts(): List<Account> {
        accountsCallCount++
        return accountsList
    }

    override suspend fun changesSince(accountId: String, cursor: String?): ChangePage {
        calls += accountId to cursor
        failNextChangesSince?.let {
            failNextChangesSince = null
            throw it
        }
        val index = callIndex.getOrDefault(accountId, 0)
        val page = pages.getValue(accountId)[index]
        callIndex[accountId] = index + 1
        return page
    }
}

class SyncManagerTest {
    private val accountA = Account("acc-a", "Ada")
    private val accountB = Account("acc-b", "Bob")

    private fun cursorFile(): File = File.createTempFile("cursors", ".json").apply { deleteOnExit() }

    @Test
    fun pagesThroughChangesUntilNoNextCursorAndReportsProgress() = runTest {
        val api = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf(
                "acc-a" to listOf(
                    ChangePage(items = listOf("1"), nextCursor = "c1"),
                    ChangePage(items = listOf("2"), nextCursor = "c2"),
                    ChangePage(items = listOf("3"), nextCursor = null),
                ),
            ),
        )
        val manager = SyncManager(api, CursorStore(cursorFile()), SyncStatusStore())

        val progress = manager.sync().toList()

        assertEquals(3, api.calls.count { it.first == "acc-a" })
        assertEquals(listOf(null, "c1", "c2"), api.calls.map { it.second })
        assertEquals(
            listOf(
                SyncProgress(0, 1, null),
                SyncProgress(1, 1, accountA),
            ),
            progress,
        )
    }

    @Test
    fun syncsMultipleAccountsIndependently() = runTest {
        val api = FakeAccountApi(
            accountsList = listOf(accountA, accountB),
            pages = mapOf(
                "acc-a" to listOf(ChangePage(items = emptyList(), nextCursor = null)),
                "acc-b" to listOf(ChangePage(items = emptyList(), nextCursor = null)),
            ),
        )
        val manager = SyncManager(api, CursorStore(cursorFile()), SyncStatusStore())

        val progress = manager.sync().toList()

        assertEquals(
            listOf(
                SyncProgress(0, 2, null),
                SyncProgress(1, 2, accountA),
                SyncProgress(2, 2, accountB),
            ),
            progress,
        )
    }

    @Test
    fun persistsCursorSoNextSyncResumes() = runTest {
        val file = cursorFile()
        val firstApi = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf(
                "acc-a" to listOf(
                    ChangePage(items = listOf("1"), nextCursor = "c1"),
                    ChangePage(items = listOf("2"), nextCursor = null),
                ),
            ),
        )
        SyncManager(firstApi, CursorStore(file), SyncStatusStore()).sync().toList()

        assertEquals(listOf(null, "c1"), firstApi.calls.map { it.second })
        assertEquals(mapOf("acc-a" to "c1"), CursorStore(file).load())

        val secondApi = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf(
                "acc-a" to listOf(ChangePage(items = listOf("3"), nextCursor = null)),
            ),
        )
        SyncManager(secondApi, CursorStore(file), SyncStatusStore()).sync().toList()

        assertEquals(listOf("c1"), secondApi.calls.map { it.second })
    }

    @Test
    fun recordsSuccessOnStatusStore() = runTest {
        val api = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf("acc-a" to listOf(ChangePage(items = emptyList(), nextCursor = null))),
        )
        val statusStore = SyncStatusStore()
        val fixedNow = Instant.parse("2026-01-01T00:00:00Z")
        val manager = SyncManager(api, CursorStore(cursorFile()), statusStore, now = { fixedNow })

        manager.sync().toList()

        assertEquals(fixedNow, statusStore.status.value.lastSyncTime)
        assertNull(statusStore.status.value.lastError)
    }

    @Test
    fun recordsErrorOnStatusStoreAndRethrows() = runTest {
        val api = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf("acc-a" to listOf(ChangePage(items = emptyList(), nextCursor = null))),
        )
        api.failNextChangesSince = RuntimeException("boom")
        val statusStore = SyncStatusStore()
        val manager = SyncManager(api, CursorStore(cursorFile()), statusStore)

        assertTrue(runCatching { manager.sync().toList() }.isFailure)
        assertEquals("boom", statusStore.status.value.lastError)
        assertNull(statusStore.status.value.lastSyncTime)
    }

    @OptIn(kotlinx.coroutines.ExperimentalCoroutinesApi::class)
    @Test
    fun startPeriodicSyncRunsImmediatelyAndThenEveryInterval() = runTest {
        val api = FakeAccountApi(
            accountsList = listOf(accountA),
            pages = mapOf("acc-a" to List(10) { ChangePage(items = emptyList(), nextCursor = null) }),
        )
        val manager = SyncManager(api, CursorStore(cursorFile()), SyncStatusStore())

        val job = manager.startPeriodicSync(scope = this, interval = 15.minutes)
        runCurrent()
        assertEquals(1, api.accountsCallCount)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(2, api.accountsCallCount)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(3, api.accountsCallCount)

        job.cancel()
    }

    @Test
    fun cursorStoreReturnsEmptyMapWhenFileMissing() {
        val missing = File.createTempFile("cursors", ".json").apply { delete() }
        assertEquals(emptyMap(), CursorStore(missing).load())
    }

    @Test
    fun cursorStoreRoundTripsThroughJson() {
        val file = cursorFile()
        val store = CursorStore(file)
        store.save(mapOf("acc-a" to "c1", "acc-b" to "c9"))

        val reloaded = CursorStore(file).load()

        assertEquals(mapOf("acc-a" to "c1", "acc-b" to "c9"), reloaded)
        assertNotNull(file.readText())
    }
}

use std::future::Future;
use std::io;
use std::net::SocketAddr;
use std::path::Path;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use tokio::fs::{File, OpenOptions};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, Mutex};
use tokio::time::timeout;

pub const DEFAULT_IDLE_TIMEOUT: Duration = Duration::from_secs(5 * 60);
const BROADCAST_CAPACITY: usize = 256;

/// Binds `addr` and serves chat clients until Ctrl-C is received.
pub async fn run(addr: &str, log_path: impl AsRef<Path>) -> io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    println!("chat server listening on {}", listener.local_addr()?);
    serve(listener, log_path, DEFAULT_IDLE_TIMEOUT, async {
        let _ = tokio::signal::ctrl_c().await;
    })
    .await
}

/// Accepts connections from `listener` until `shutdown` resolves.
///
/// Split out from [`run`] so tests can bind an ephemeral port, use a short
/// idle timeout, and trigger shutdown without touching Ctrl-C / real time.
pub async fn serve(
    listener: TcpListener,
    log_path: impl AsRef<Path>,
    idle_timeout: Duration,
    shutdown: impl Future<Output = ()>,
) -> io::Result<()> {
    tokio::pin!(shutdown);

    let (tx, _rx) = broadcast::channel::<(SocketAddr, String)>(BROADCAST_CAPACITY);
    let user_count = Arc::new(AtomicUsize::new(0));
    let file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path.as_ref())
        .await?;
    let log = Arc::new(Mutex::new(file));

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                let (socket, addr) = match accept_res {
                    Ok(pair) => pair,
                    Err(e) => {
                        eprintln!("accept error: {e}");
                        continue;
                    }
                };
                let tx = tx.clone();
                let user_count = user_count.clone();
                let log = log.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(socket, addr, tx, user_count, log, idle_timeout).await {
                        eprintln!("client {addr} error: {e}");
                    }
                });
            }
            _ = &mut shutdown => break,
        }
    }

    Ok(())
}

async fn handle_client(
    socket: TcpStream,
    addr: SocketAddr,
    tx: broadcast::Sender<(SocketAddr, String)>,
    user_count: Arc<AtomicUsize>,
    log: Arc<Mutex<File>>,
    idle_timeout: Duration,
) -> io::Result<()> {
    let (read_half, mut writer) = socket.into_split();
    let mut lines = BufReader::new(read_half).lines();

    let nick = match timeout(idle_timeout, lines.next_line()).await {
        Ok(Ok(Some(line))) => line.trim().to_string(),
        Ok(Ok(None)) | Err(_) => return Ok(()),
        Ok(Err(e)) => return Err(e),
    };
    if nick.is_empty() {
        return Ok(());
    }

    user_count.fetch_add(1, Ordering::SeqCst);
    let mut rx = tx.subscribe();

    let result = client_loop(
        &mut lines,
        &mut writer,
        &mut rx,
        addr,
        &nick,
        &tx,
        &user_count,
        &log,
        idle_timeout,
    )
    .await;

    user_count.fetch_sub(1, Ordering::SeqCst);
    result
}

#[allow(clippy::too_many_arguments)]
async fn client_loop(
    lines: &mut tokio::io::Lines<BufReader<tokio::net::tcp::OwnedReadHalf>>,
    writer: &mut tokio::net::tcp::OwnedWriteHalf,
    rx: &mut broadcast::Receiver<(SocketAddr, String)>,
    addr: SocketAddr,
    nick: &str,
    tx: &broadcast::Sender<(SocketAddr, String)>,
    user_count: &Arc<AtomicUsize>,
    log: &Arc<Mutex<File>>,
    idle_timeout: Duration,
) -> io::Result<()> {
    loop {
        tokio::select! {
            line_res = timeout(idle_timeout, lines.next_line()) => {
                let text = match line_res {
                    Ok(Ok(Some(text))) => text,
                    Ok(Ok(None)) => break,
                    Ok(Err(e)) => return Err(e),
                    Err(_elapsed) => {
                        let _ = writer.write_all(b"idle timeout, disconnecting\n").await;
                        break;
                    }
                };
                let text = text.trim();
                if text.is_empty() {
                    continue;
                }
                if text == "/who" {
                    let count = user_count.load(Ordering::SeqCst);
                    let msg = format!("{count} user(s) connected\n");
                    writer.write_all(msg.as_bytes()).await?;
                    continue;
                }
                let formatted = format!("{nick}: {text}");
                log_line(log, &formatted).await?;
                let _ = tx.send((addr, format!("{formatted}\n")));
            }
            recv_res = rx.recv() => {
                match recv_res {
                    Ok((from_addr, msg)) => {
                        if from_addr != addr {
                            writer.write_all(msg.as_bytes()).await?;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        }
    }
    Ok(())
}

async fn log_line(log: &Arc<Mutex<File>>, line: &str) -> io::Result<()> {
    let mut file = log.lock().await;
    file.write_all(line.as_bytes()).await?;
    file.write_all(b"\n").await?;
    file.flush().await
}

