    let creds = ApiCredentials {
        client_id: "client".to_string(),
        client_secret: "secret".to_string(),
        access_token: "token".to_string(),
        expires_at: 0,
    };

    assert_eq!(creds.seconds_until_expiry(), 0);
}

#[test]
fn profile_search_sql_uses_placeholders_not_interpolation() {
    let query = profile_search_sql("Ann", "eng");

    assert!(query.sql.contains("?1"));
    assert!(query.sql.contains("?2"));
    assert!(!query.sql.contains("Ann"));
    assert!(!query.sql.contains("eng"));
    assert_eq!(query.params, vec!["Ann%".to_string(), "eng".to_string()]);
}

#[test]
fn profile_search_sql_keeps_injection_payloads_out_of_the_statement() {
    let query = profile_search_sql("Ann'; DROP TABLE profiles;--", "eng");

    assert!(!query.sql.contains("DROP TABLE"));
    assert_eq!(query.params[0], "Ann'; DROP TABLE profiles;--%");
}

//! A small line-based TCP chat server.
//!
//! Each connecting client sends a nickname as its first line, then every
//! subsequent line it sends is broadcast to all other connected clients as
//! `nick: line`. Sending `/who` prints the number of connected clients back
//! to the sender instead of being broadcast. Clients idle for longer than
//! the configured timeout are disconnected. Every chat message is appended
//! to a log file.

use std::future::Future;
use std::io;
use std::net::SocketAddr;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use tokio::fs::OpenOptions;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, Mutex};

/// How long a client may stay idle (no line received) before being dropped.
const DEFAULT_IDLE_TIMEOUT: Duration = Duration::from_secs(5 * 60);

static NEXT_CLIENT_ID: AtomicU64 = AtomicU64::new(0);

#[derive(Clone)]
struct ChatMessage {
    sender_id: u64,
    text: String,
}

/// A running (but not yet started) chat server bound to a socket.
pub struct ChatServer {
    listener: TcpListener,
    log_path: PathBuf,
    idle_timeout: Duration,
    user_count: Arc<AtomicUsize>,
}

impl ChatServer {
    /// Bind the server to `addr`, logging chat messages to `log_path`.
    pub async fn bind(addr: &str, log_path: impl Into<PathBuf>) -> io::Result<Self> {
        let listener = TcpListener::bind(addr).await?;
        Ok(Self {
            listener,
            log_path: log_path.into(),
            idle_timeout: DEFAULT_IDLE_TIMEOUT,
            user_count: Arc::new(AtomicUsize::new(0)),
        })
    }

    /// Override the idle timeout (defaults to 5 minutes).
    pub fn with_idle_timeout(mut self, idle_timeout: Duration) -> Self {
        self.idle_timeout = idle_timeout;
        self
    }

    /// The address this server actually bound to (useful when binding to port 0).
    pub fn local_addr(&self) -> io::Result<SocketAddr> {
        self.listener.local_addr()
    }

    /// A handle to the live connected-user count.
    pub fn user_count_handle(&self) -> Arc<AtomicUsize> {
        self.user_count.clone()
    }

    /// Accept connections until `shutdown` resolves, then stop cleanly.
    /// Already-connected clients are allowed to finish on their own.
    pub async fn run(self, shutdown: impl Future<Output = ()>) -> io::Result<()> {
        let (tx, _rx) = broadcast::channel::<ChatMessage>(256);
        let log_file = Arc::new(Mutex::new(
            OpenOptions::new()
                .create(true)
                .append(true)
                .open(&self.log_path)
                .await?,
        ));

        tokio::pin!(shutdown);
        loop {
            tokio::select! {
                _ = &mut shutdown => break,
                accepted = self.listener.accept() => {
                    let (socket, _addr) = match accepted {
                        Ok(pair) => pair,
                        Err(_) => continue,
                    };
                    let tx = tx.clone();
                    let rx = tx.subscribe();
                    let user_count = self.user_count.clone();
                    let log_file = log_file.clone();
                    let idle_timeout = self.idle_timeout;
                    tokio::spawn(async move {
                        handle_client(socket, tx, rx, user_count, log_file, idle_timeout).await;
                    });
                }
            }
        }
        Ok(())
    }
}

async fn log_line(log_file: &Mutex<tokio::fs::File>, line: &str) {
    let mut file = log_file.lock().await;
    let _ = file.write_all(line.as_bytes()).await;
    let _ = file.write_all(b"\n").await;
    let _ = file.flush().await;
}

async fn handle_client(
    socket: TcpStream,
    tx: broadcast::Sender<ChatMessage>,
    mut rx: broadcast::Receiver<ChatMessage>,
    user_count: Arc<AtomicUsize>,
    log_file: Arc<Mutex<tokio::fs::File>>,
    idle_timeout: Duration,
) {
    let (read_half, mut writer) = socket.into_split();
    let mut lines = BufReader::new(read_half).lines();

    let nick = match tokio::time::timeout(idle_timeout, lines.next_line()).await {
        Ok(Ok(Some(line))) if !line.trim().is_empty() => line.trim().to_string(),
        _ => return,
    };

    let id = NEXT_CLIENT_ID.fetch_add(1, Ordering::SeqCst);
    user_count.fetch_add(1, Ordering::SeqCst);

    loop {
        tokio::select! {
            line = tokio::time::timeout(idle_timeout, lines.next_line()) => {
                match line {
                    Ok(Ok(Some(text))) => {
                        let text = text.trim();
                        if text.is_empty() {
                            continue;
                        }
                        if text == "/who" {
                            let count = user_count.load(Ordering::SeqCst);
                            let reply = format!("{count} user(s) connected\n");
                            if writer.write_all(reply.as_bytes()).await.is_err() {
                                break;
                            }
                            continue;
                        }
                        let formatted = format!("{nick}: {text}");
                        log_line(&log_file, &formatted).await;
                        let _ = tx.send(ChatMessage { sender_id: id, text: formatted });
                    }
                    Ok(Ok(None)) => break,
                    Ok(Err(_)) => break,
                    Err(_) => break, // idle timeout elapsed
                }
            }
            msg = rx.recv() => {
                match msg {
                    Ok(m) if m.sender_id != id => {
                        let line = format!("{}\n", m.text);
                        if writer.write_all(line.as_bytes()).await.is_err() {
                            break;
                        }
                    }
                    Ok(_) => {}
                    Err(broadcast::error::RecvError::Lagged(_)) => {}
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        }
    }

    user_count.fetch_sub(1, Ordering::SeqCst);
}

/// Bind and run a chat server on `addr` until Ctrl-C is received, logging to `log_path`.
pub async fn run(addr: &str, log_path: impl Into<PathBuf>) -> io::Result<()> {
    let server = ChatServer::bind(addr, log_path).await?;
    println!("chat server listening on {}", server.local_addr()?);
    server
        .run(async {
            let _ = tokio::signal::ctrl_c().await;
        })
        .await
}

