use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use relay::chat::ChatServer;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
use tokio::net::TcpStream;
use tokio::sync::oneshot;
use tokio::task::JoinHandle;

struct TestServer {
    addr: std::net::SocketAddr,
    user_count: Arc<AtomicUsize>,
    log_path: PathBuf,
    shutdown: Option<oneshot::Sender<()>>,
    handle: Option<JoinHandle<()>>,
}

impl TestServer {
    async fn start(idle_timeout: Duration) -> Self {
        let log_path = std::env::temp_dir().join(format!(
            "chat_test_{}_{}.log",
            std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()
        ));

        let server = ChatServer::bind("127.0.0.1:0", &log_path)
            .await
            .expect("bind")
            .with_idle_timeout(idle_timeout);
        let addr = server.local_addr().expect("local_addr");
        let user_count = server.user_count_handle();

        let (shutdown_tx, shutdown_rx) = oneshot::channel();
        let handle = tokio::spawn(async move {
            server
                .run(async {
                    let _ = shutdown_rx.await;
                })
                .await
                .expect("server run");
        });

        Self {
            addr,
            user_count,
            log_path,
            shutdown: Some(shutdown_tx),
            handle: Some(handle),
        }
    }

    async fn stop(mut self) {
        if let Some(tx) = self.shutdown.take() {
            let _ = tx.send(());
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.await;
        }
        let _ = tokio::fs::remove_file(&self.log_path).await;
    }
}

async fn connect(addr: std::net::SocketAddr, nick: &str) -> TcpStream {
    let mut stream = TcpStream::connect(addr).await.expect("connect");
    stream
        .write_all(format!("{nick}\n").as_bytes())
        .await
        .expect("send nick");
    stream
}

async fn read_line(stream: &mut TcpStream) -> String {
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    reader.read_line(&mut line).await.expect("read line");
    line.trim_end().to_string()
}

#[tokio::test]
async fn broadcasts_messages_to_other_clients_only() {
    let server = TestServer::start(Duration::from_secs(300)).await;

    let mut alice = connect(server.addr, "alice").await;
    let mut bob = connect(server.addr, "bob").await;
    tokio::time::sleep(Duration::from_millis(50)).await;

    alice
        .write_all(b"hello there\n")
        .await
        .expect("send message");

    let received = read_line(&mut bob).await;
    assert_eq!(received, "alice: hello there");

    server.stop().await;
}

#[tokio::test]
async fn who_reports_connected_user_count() {
    let server = TestServer::start(Duration::from_secs(300)).await;

    let mut alice = connect(server.addr, "alice").await;
    let _bob = connect(server.addr, "bob").await;
    tokio::time::sleep(Duration::from_millis(50)).await;

    alice.write_all(b"/who\n").await.expect("send /who");
    let reply = read_line(&mut alice).await;
    assert_eq!(reply, "2 user(s) connected");

    server.stop().await;
}

#[tokio::test]
async fn tracks_connected_user_count_on_connect_and_disconnect() {
    let server = TestServer::start(Duration::from_secs(300)).await;
    assert_eq!(server.user_count.load(Ordering::SeqCst), 0);

    let client = connect(server.addr, "nick1").await;
    tokio::time::sleep(Duration::from_millis(50)).await;
    assert_eq!(server.user_count.load(Ordering::SeqCst), 1);

    drop(client);
    tokio::time::sleep(Duration::from_millis(50)).await;
    assert_eq!(server.user_count.load(Ordering::SeqCst), 0);

    server.stop().await;
}

