package com.acme.app.sync

import com.acme.app.data.Account
import com.acme.app.data.AccountApi
import java.io.File
import kotlin.time.Duration
import kotlin.time.Duration.Companion.minutes
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.collect
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

data class SyncProgress(
    val accountsDone: Int,
    val accountsTotal: Int,
    val currentAccount: Account?,
)

@Serializable
private data class CursorState(val cursors: Map<String, String?> = emptyMap())

/**
 * Syncs every account's changes via [AccountApi], paging through `changesSince` until a page
 * comes back with no next cursor. Each account's last cursor is persisted to [cursorStoreFile]
 * after every page, so a later sync (e.g. after a crash or restart) resumes from where it left
 * off instead of re-reading the whole history.
 */
class SyncManager(
    private val accountApi: AccountApi,
    private val cursorStoreFile: File,
    val statusStore: SyncStatusStore = SyncStatusStore(),
) {
    private val json = Json { ignoreUnknownKeys = true }

    /** Syncs all accounts once, emitting progress as each one starts and finishes. */
    fun sync(): Flow<SyncProgress> = flow {
        val cursors = loadCursors().toMutableMap()
        val accounts = accountApi.accounts()
        var firstError: Throwable? = null

        emit(SyncProgress(accountsDone = 0, accountsTotal = accounts.size, currentAccount = null))
        accounts.forEachIndexed { index, account ->
            emit(SyncProgress(index, accounts.size, account))
            try {
                syncAccount(account, cursors)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                if (firstError == null) firstError = e
            }
            emit(SyncProgress(index + 1, accounts.size, account))
        }

        val error = firstError
        if (error != null) statusStore.recordFailure(error) else statusStore.recordSuccess()
    }

    /** Starts syncing immediately, then again every [interval], until the returned [Job] is cancelled. */
    fun startPeriodicSync(scope: CoroutineScope, interval: Duration = 15.minutes): Job =
        scope.launch {
            while (isActive) {
                sync().collect()
                delay(interval)
            }
        }

    private suspend fun syncAccount(account: Account, cursors: MutableMap<String, String?>) {
        var cursor = cursors[account.id]
        while (true) {
            val page = accountApi.changesSince(account.id, cursor)
            if (page.nextCursor == null) break
            cursor = page.nextCursor
            cursors[account.id] = cursor
            saveCursors(cursors)
        }
    }

    private suspend fun loadCursors(): Map<String, String?> = withContext(Dispatchers.IO) {
        if (!cursorStoreFile.exists()) return@withContext emptyMap()
        try {
            json.decodeFromString<CursorState>(cursorStoreFile.readText()).cursors
        } catch (e: Exception) {
            emptyMap()
        }
    }

    private suspend fun saveCursors(cursors: Map<String, String?>) = withContext(Dispatchers.IO) {
        cursorStoreFile.parentFile?.mkdirs()
        cursorStoreFile.writeText(json.encodeToString(CursorState(cursors)))
    }
}

package com.acme.app.sync

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.time.Instant

data class SyncStatus(
    val lastSyncTime: Instant? = null,
    val lastError: Throwable? = null,
)

/** Observable last-sync-time/error state, updated by [SyncManager] and read by the UI. */
class SyncStatusStore {
    private val _status = MutableStateFlow(SyncStatus())
    val status: StateFlow<SyncStatus> = _status.asStateFlow()

    fun recordSuccess(time: Instant = Instant.now()) {
        _status.value = SyncStatus(lastSyncTime = time, lastError = null)
    }

    fun recordFailure(error: Throwable, time: Instant = Instant.now()) {
        _status.value = SyncStatus(lastSyncTime = time, lastError = error)
    }
}

package com.acme.app.sync

import com.acme.app.data.Account
import com.acme.app.data.AccountApi
