import kotlin.test.assertNull
import kotlin.test.assertTrue
import kotlin.time.Duration.Companion.minutes
import kotlinx.coroutines.flow.toList
import kotlinx.coroutines.test.advanceTimeBy
import kotlinx.coroutines.test.runCurrent
import kotlinx.coroutines.test.runTest

private class FakeAccountApi(
    private val accountsList: List<Account>,
    private val pages: MutableMap<Pair<String, String?>, ChangePage>,
    private val failFor: Set<String> = emptySet(),
) : AccountApi {
    val calls = mutableListOf<Pair<String, String?>>()

    override suspend fun accounts(): List<Account> = accountsList

    override suspend fun changesSince(accountId: String, cursor: String?): ChangePage {
        calls += accountId to cursor
        if (accountId in failFor) error("boom for $accountId")
        return pages[accountId to cursor] ?: error("no page stubbed for $accountId at cursor=$cursor")
    }
}

class SyncManagerTest {
    private fun tempCursorFile(): File = File.createTempFile("cursors", ".json").apply { deleteOnExit() }

    @Test
    fun `pages through changesSince until there is no next cursor`() = runTest {
        val account = Account("a1", "Ada")
        val pages = mutableMapOf(
            (account.id to null as String?) to ChangePage(listOf("c1"), "p1"),
            (account.id to "p1" as String?) to ChangePage(listOf("c2"), "p2"),
            (account.id to "p2" as String?) to ChangePage(listOf("c3"), null),
        )
        val api = FakeAccountApi(listOf(account), pages)
        val manager = SyncManager(api, tempCursorFile())

        manager.sync().toList()

        assertEquals(
            listOf(account.id to null, account.id to "p1", account.id to "p2"),
            api.calls,
        )
    }

    @Test
    fun `reports progress for each account`() = runTest {
        val a1 = Account("a1", "Ada")
        val a2 = Account("a2", "Bo")
        val pages = mutableMapOf(
            (a1.id to null as String?) to ChangePage(emptyList(), null),
            (a2.id to null as String?) to ChangePage(emptyList(), null),
        )
        val api = FakeAccountApi(listOf(a1, a2), pages)
        val manager = SyncManager(api, tempCursorFile())

        val progress = manager.sync().toList()

        assertEquals(
            listOf(
                SyncProgress(0, 2, null),
                SyncProgress(0, 2, a1),
                SyncProgress(1, 2, a1),
                SyncProgress(1, 2, a2),
                SyncProgress(2, 2, a2),
            ),
            progress,
        )
    }

    @Test
    fun `a later sync resumes from the persisted cursor`() = runTest {
        val account = Account("a1", "Ada")
        val file = tempCursorFile()

        val firstPages = mutableMapOf(
            (account.id to null as String?) to ChangePage(listOf("c1"), "p1"),
            (account.id to "p1" as String?) to ChangePage(listOf("c2"), null),
        )
        val firstApi = FakeAccountApi(listOf(account), firstPages)
        SyncManager(firstApi, file).sync().toList()
        assertEquals(listOf(account.id to null, account.id to "p1"), firstApi.calls)

        val secondPages = mutableMapOf(
            (account.id to "p1" as String?) to ChangePage(listOf("c3"), null),
        )
        val secondApi = FakeAccountApi(listOf(account), secondPages)
        SyncManager(secondApi, file).sync().toList()

        assertEquals(listOf(account.id to "p1"), secondApi.calls)
    }

    @Test
    fun `one account failing does not stop other accounts or the flow`() = runTest {
        val ok = Account("a1", "Ada")
        val broken = Account("a2", "Bo")
        val pages = mutableMapOf(
            (ok.id to null as String?) to ChangePage(listOf("c1"), null),
        )
        val api = FakeAccountApi(listOf(broken, ok), pages, failFor = setOf(broken.id))
        val manager = SyncManager(api, tempCursorFile())

        val progress = manager.sync().toList()

        assertEquals(SyncProgress(2, 2, ok), progress.last())
        assertTrue(api.calls.contains(ok.id to null))
        assertNotNull(manager.statusStore.status.value.lastError)
    }

    @Test
    fun `successful sync clears any previous error and records the time`() = runTest {
        val account = Account("a1", "Ada")
        val pages = mutableMapOf((account.id to null as String?) to ChangePage(emptyList(), null))
        val api = FakeAccountApi(listOf(account), pages)
        val statusStore = SyncStatusStore()
        statusStore.recordFailure(RuntimeException("stale error from a previous run"))
        val manager = SyncManager(api, tempCursorFile(), statusStore)

        manager.sync().toList()

        val status = statusStore.status.value
        assertNull(status.lastError)
        assertNotNull(status.lastSyncTime)
    }

    @Test
    fun `periodic sync runs immediately and then every interval`() = runTest {
        val account = Account("a1", "Ada")
        val pages = mutableMapOf((account.id to null as String?) to ChangePage(emptyList(), null))
        val api = FakeAccountApi(listOf(account), pages)
        val manager = SyncManager(api, tempCursorFile())

        manager.startPeriodicSync(backgroundScope, interval = 15.minutes)
        runCurrent()
        assertEquals(1, api.calls.size)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(2, api.calls.size)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(3, api.calls.size)
    }
}

//! relay: a small Tokio service. Add modules below.

pub mod config;
pub mod profiles;

//! Profile loading with an in-memory TTL cache, plus API credential and
//! reporting-query helpers used alongside it.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use thiserror::Error;
use tokio::sync::Mutex;
use tokio::time::Instant;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Profile {
    pub id: String,
    pub name: String,
    pub team: String,
    pub email: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum BackendError {
    #[error("profile not found: {0}")]
    NotFound(String),
    #[error("backend error: {0}")]
    Other(String),
}

/// Source of truth for profiles; `ProfileService` caches results in front of it.
pub trait ProfileBackend: Send + Sync {
    fn fetch(&self, id: &str) -> impl std::future::Future<Output = Result<Profile, BackendError>> + Send;
}

struct CacheEntry {
    profile: Profile,
    inserted_at: Instant,
}

struct Inner<B> {
    backend: B,
    ttl: Duration,
    cache: Mutex<HashMap<String, CacheEntry>>,
}

pub struct ProfileService<B> {
    inner: Arc<Inner<B>>,
}

impl<B> Clone for ProfileService<B> {
    fn clone(&self) -> Self {
        Self {
            inner: Arc::clone(&self.inner),
        }
    }
}

impl<B: ProfileBackend + Send + Sync + 'static> ProfileService<B> {
    pub fn new(backend: B, ttl: Duration) -> Self {
        Self {
            inner: Arc::new(Inner {
                backend,
                ttl,
                cache: Mutex::new(HashMap::new()),
            }),
        }
    }

    pub async fn load(&self, id: &str) -> Result<Profile, BackendError> {
        {
            let cache = self.inner.cache.lock().await;
            if let Some(entry) = cache.get(id) {
                if entry.inserted_at.elapsed() < self.inner.ttl {
                    return Ok(entry.profile.clone());
                }
            }
        }

        let profile = self.inner.backend.fetch(id).await?;
        let mut cache = self.inner.cache.lock().await;
        cache.insert(
            id.to_string(),
            CacheEntry {
                profile: profile.clone(),
                inserted_at: Instant::now(),
            },
        );
        Ok(profile)
    }

    /// Loads a batch of profiles for the team page, one result per id, in the
    /// same order as `ids`, fetching concurrently so a slow or large roster
    /// doesn't pay for one network round trip per member.
    pub async fn load_many(&self, ids: &[String]) -> Vec<(String, Result<Profile, BackendError>)> {
        let mut tasks = tokio::task::JoinSet::new();
        for (index, id) in ids.iter().cloned().enumerate() {
            let service = self.clone();
            tasks.spawn(async move {
                let result = service.load(&id).await;
                (index, id, result)
            });
        }

        let mut results: Vec<Option<(String, Result<Profile, BackendError>)>> =
            (0..ids.len()).map(|_| None).collect();
        while let Some(outcome) = tasks.join_next().await {
            let (index, id, result) = outcome.expect("load task panicked");
            results[index] = Some((id, result));
        }
        results
            .into_iter()
            .map(|entry| entry.expect("every spawned load task reports back"))
            .collect()
    }
}

#[derive(Clone, PartialEq, Eq)]
pub struct ApiCredentials {
    pub client_id: String,
    pub client_secret: String,
    pub access_token: String,
    pub expires_at: i64,
}

impl std::fmt::Debug for ApiCredentials {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ApiCredentials")
            .field("client_id", &self.client_id)
            .field("client_secret", &"[redacted]")
            .field("access_token", &"[redacted]")
            .field("expires_at", &self.expires_at)
            .finish()
    }
}

impl ApiCredentials {
    /// Seconds left before `access_token` expires, clamped to 0 once it has.
    pub fn seconds_remaining(&self) -> i64 {
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock is before the Unix epoch")
            .as_secs() as i64;
        (self.expires_at - now).max(0)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileSearchQuery {
    pub sql: String,
    pub params: Vec<String>,
}

/// Builds the SELECT the reporting job runs against SQLite for a profile
/// search. `name_prefix` and `team` are bound as `?` parameters rather than
/// spliced into the SQL text, so they can't be used to alter the query.
pub fn profile_search_sql(name_prefix: &str, team: &str) -> ProfileSearchQuery {
    ProfileSearchQuery {
        sql: "SELECT id, name, team, email FROM profiles WHERE name LIKE ? AND team = ? ORDER BY name"
            .to_string(),
        params: vec![format!("{name_prefix}%"), team.to_string()],
    }
}

use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use relay::profiles::{
    profile_search_sql, ApiCredentials, BackendError, Profile, ProfileBackend, ProfileService,
};
use tokio::sync::Mutex;

#[derive(Clone)]
struct FakeBackend {
    profiles: Arc<Mutex<HashMap<String, Profile>>>,
    fetch_count: Arc<AtomicUsize>,
}

impl FakeBackend {
    fn new(profiles: Vec<Profile>) -> Self {
        let map = profiles.into_iter().map(|p| (p.id.clone(), p)).collect();
        Self {
            profiles: Arc::new(Mutex::new(map)),
            fetch_count: Arc::new(AtomicUsize::new(0)),
        }
    }

    fn fetch_count(&self) -> usize {
        self.fetch_count.load(Ordering::SeqCst)
    }
}

impl ProfileBackend for FakeBackend {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError> {
        self.fetch_count.fetch_add(1, Ordering::SeqCst);
        let profiles = self.profiles.lock().await;
        profiles
            .get(id)
            .cloned()
            .ok_or_else(|| BackendError::NotFound(id.to_string()))
    }
}

fn sample_profile(id: &str) -> Profile {
    Profile {
        id: id.to_string(),
        name: format!("User {id}"),
        team: "eng".to_string(),
        email: format!("{id}@example.com"),
    }
}

#[tokio::test]
async fn load_returns_profile_from_backend() {
    let backend = FakeBackend::new(vec![sample_profile("1")]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let profile = service.load("1").await.unwrap();
    assert_eq!(profile.id, "1");
    assert_eq!(profile.name, "User 1");
}

#[tokio::test]
async fn load_propagates_backend_error_for_missing_profile() {
    let backend = FakeBackend::new(vec![]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let err = service.load("missing").await.unwrap_err();
    assert_eq!(err, BackendError::NotFound("missing".to_string()));
}

#[tokio::test(start_paused = true)]
async fn load_caches_within_ttl_and_refetches_after_expiry() {
    let backend = FakeBackend::new(vec![sample_profile("1")]);
    let service = ProfileService::new(backend.clone(), Duration::from_secs(30));

    service.load("1").await.unwrap();
    assert_eq!(backend.fetch_count(), 1);

    service.load("1").await.unwrap();
    assert_eq!(
        backend.fetch_count(),
        1,
        "second load within ttl should hit cache"
    );

    tokio::time::advance(Duration::from_secs(31)).await;

    service.load("1").await.unwrap();
    assert_eq!(
        backend.fetch_count(),
        2,
        "load after ttl expiry should refetch"
    );
}

#[tokio::test]
async fn load_many_returns_result_per_id_preserving_order() {
    let backend = FakeBackend::new(vec![sample_profile("1"), sample_profile("2")]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let ids = vec!["1".to_string(), "missing".to_string(), "2".to_string()];
    let results = service.load_many(&ids).await;

    assert_eq!(results.len(), 3);
    assert_eq!(results[0].0, "1");
    assert!(results[0].1.is_ok());
    assert_eq!(results[1].0, "missing");
    assert!(matches!(results[1].1, Err(BackendError::NotFound(_))));
    assert_eq!(results[2].0, "2");
    assert!(results[2].1.is_ok());
}

#[test]
fn seconds_remaining_reflects_future_expiry() {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
