import csv
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path

# Base state sales tax rate only; does not include county/city/district add-ons.
_RATES_CSV = Path(__file__).resolve().parent / "tax_rates.csv"


def load_rates(path: Path = _RATES_CSV) -> dict[str, Decimal]:
    with path.open("r", newline="") as f:
        return {row["state"].strip().upper(): Decimal(row["rate"]) for row in csv.DictReader(f)}


_RATES = load_rates()


def tax_rate(state: str) -> Decimal:
    try:
        return _RATES[state.strip().upper()]
    except KeyError:
        raise ValueError(f"no sales tax rate on file for state code {state!r}") from None


def sales_tax(amount: Decimal, state: str) -> Decimal:
    return (amount * tax_rate(state)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

