"""US state sales tax lookup and calculation.

Rates in tax_rates.csv are base state-level sales tax rates and do not
include county/city surtaxes. They are illustrative, not a substitute for
an authoritative tax data provider.
"""

import csv
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path

_RATES_PATH = Path(__file__).parent / "tax_rates.csv"


def _load_rates(path: Path = _RATES_PATH) -> dict[str, Decimal]:
    with path.open(newline="") as f:
        return {row["state"]: Decimal(row["rate"]) for row in csv.DictReader(f)}


_RATES = _load_rates()


def tax_rate(state: str) -> Decimal:
    """Return the sales tax rate for a two-letter US state/DC code."""
    try:
        return _RATES[state.upper()]
    except KeyError:
        raise ValueError(f"Unknown state code: {state!r}") from None


def sales_tax(amount: Decimal, state: str) -> Decimal:
    """Return the sales tax owed on amount for the given state, rounded to cents."""
    return (amount * tax_rate(state)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def total_with_tax(amount: Decimal, state: str) -> Decimal:
    """Return amount plus sales tax for the given state."""
    return amount + sales_tax(amount, state)

