// A small notes HTTP API built on web-standard fetch primitives (Request/Response/URL/crypto.subtle).

export interface StoredUser {
  id: string;
  username: string;
  passwordHash: string;
  passwordSalt: string;
  createdAt: number;
}

export interface Note {
  id: string;
  userId: string;
  title: string;
  body: string;
  updatedAt: number;
}

export interface NotePatch {
  title?: string;
  body?: string;
}

export interface Db {
  users: {
    findByUsername(username: string): Promise<StoredUser | null>;
    findById(id: string): Promise<StoredUser | null>;
    insert(user: StoredUser): Promise<void>;
  };
  notes: {
    findById(id: string): Promise<Note | null>;
    update(id: string, patch: NotePatch): Promise<Note | null>;
  };
  // Raw access for anything that doesn't fit the typed helpers above (sessions,
  // search). Callers MUST use `params` for any user-controlled value rather
  // than interpolating into `sql`.
  query<T = unknown>(sql: string, params?: unknown[]): Promise<T[]>;
}

interface SessionRow {
  token_hash: string;
  user_id: string;
  expires_at: number;
}

const PBKDF2_ITERATIONS = 100_000;
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_IMPORT_BYTES = 1_000_000;
const PRIVATE_HOSTNAME_PATTERNS = [
  /^localhost$/i,
  /^0\.0\.0\.0$/,
  /^127\./,
  /^10\./,
  /^169\.254\./,
  /^172\.(1[6-9]|2\d|3[01])\./,
  /^192\.168\./,
  /^\[?::1\]?$/,
  /^\[?fc[0-9a-f]{2}:/i,
  /^\[?fe80:/i,
];

function toHex(bytes: ArrayBuffer | Uint8Array): string {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  return Array.from(arr, (b) => b.toString(16).padStart(2, "0")).join("");
}

function fromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return out;
}

function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

async function sha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input));
  return toHex(digest);
}

async function hashPassword(password: string, salt: Uint8Array): Promise<string> {
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveBits"]
  );
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt: salt as BufferSource, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" },
    keyMaterial,
    256
  );
  return toHex(bits);
}

function generateToken(): string {
  return toHex(crypto.getRandomValues(new Uint8Array(32)));
}

function json(status: number, body: unknown, extraHeaders?: HeadersInit): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json", ...extraHeaders },
  });
}

function badRequest(message: string): Response {
  return json(400, { error: message });
}

function unauthorized(message = "unauthorized"): Response {
  return json(401, { error: message });
}

function notFound(): Response {
  return json(404, { error: "not found" });
}

async function readJsonBody(req: Request): Promise<Record<string, unknown> | null> {
  try {
    const parsed = await req.json();
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>;
    }
    return null;
  } catch {
    return null;
  }
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function extractSessionToken(req: Request): string | null {
  const auth = req.headers.get("authorization");
  if (auth) {
    const match = /^Bearer\s+(.+)$/i.exec(auth.trim());
    if (match) return match[1];
  }
  const cookie = req.headers.get("cookie");
  if (cookie) {
    for (const part of cookie.split(";")) {
      const [rawName, ...rest] = part.trim().split("=");
      if (rawName === "session") return rest.join("=");
    }
  }
  return null;
}

async function authenticate(req: Request, db: Db): Promise<StoredUser | null> {
  const token = extractSessionToken(req);
  if (!token) return null;
  const tokenHash = await sha256Hex(token);
  const rows = await db.query<SessionRow>(
    "SELECT token_hash, user_id, expires_at FROM sessions WHERE token_hash = ?",
    [tokenHash]
  );
  const session = rows[0];
  if (!session || session.expires_at < Date.now()) return null;
  return db.users.findById(session.user_id);
}

/** Escapes LIKE metacharacters, then turns glob-style `*`/`?` into SQL `%`/`_`. */
function globToLikePattern(glob: string): string {
  let out = "";
  for (const ch of glob) {
    if (ch === "\\" || ch === "%" || ch === "_") {
      out += "\\" + ch;
    } else if (ch === "*") {
      out += "%";
    } else if (ch === "?") {
      out += "_";
    } else {
      out += ch;
    }
  }
  return out;
}

function sanitizeNextPath(rawNext: string | null): string {
  if (!rawNext) return "/";
  // Only allow same-site relative paths to avoid open-redirect via `next`.
  if (!rawNext.startsWith("/") || rawNext.startsWith("//") || rawNext.startsWith("/\\")) {
    return "/";
  }
  return rawNext;
}

function isPrivateOrLoopbackHostname(hostname: string): boolean {
  const bare = hostname.replace(/^\[|\]$/g, "");
  return PRIVATE_HOSTNAME_PATTERNS.some((pattern) => pattern.test(bare));
}

async function handleSignup(req: Request, db: Db): Promise<Response> {
  const body = await readJsonBody(req);
  const username = body?.username;
  const password = body?.password;
  if (!isNonEmptyString(username) || username.length > 64) {
    return badRequest("username is required");
  }
  if (!isNonEmptyString(password) || password.length < 8) {
    return badRequest("password must be at least 8 characters");
  }

  const existing = await db.users.findByUsername(username);
  if (existing) {
    return json(409, { error: "username already exists" });
  }

  const salt = crypto.getRandomValues(new Uint8Array(16));
  const passwordHash = await hashPassword(password, salt);
  const user: StoredUser = {
    id: crypto.randomUUID(),
    username,
    passwordHash,
    passwordSalt: toHex(salt),
    createdAt: Date.now(),
  };
  await db.users.insert(user);
  return json(201, { id: user.id, username: user.username });
}

async function handleLogin(req: Request, db: Db, url: URL): Promise<Response> {
  const body = await readJsonBody(req);
  const username = body?.username;
  const password = body?.password;
  if (!isNonEmptyString(username) || !isNonEmptyString(password)) {
    return unauthorized("invalid username or password");
  }

  const user = await db.users.findByUsername(username);
  if (!user) {
    return unauthorized("invalid username or password");
  }

  const candidateHash = await hashPassword(password, fromHex(user.passwordSalt));
  if (!constantTimeEqual(candidateHash, user.passwordHash)) {
    return unauthorized("invalid username or password");
  }

  const token = generateToken();
  const tokenHash = await sha256Hex(token);
  await db.query("INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, ?)", [
    tokenHash,
    user.id,
    Date.now() + SESSION_TTL_MS,
  ]);

  const next = sanitizeNextPath(url.searchParams.get("next"));
  return new Response(null, {
    status: 302,
    headers: {
      location: next,
      "set-cookie": `session=${token}; HttpOnly; Secure; SameSite=Lax; Path=/`,
    },
  });
}

async function handleGetNote(noteId: string, req: Request, db: Db): Promise<Response> {
  const user = await authenticate(req, db);
  if (!user) return unauthorized();

  const note = await db.notes.findById(noteId);
  if (!note || note.userId !== user.id) return notFound();
  return json(200, note);
}

async function handlePatchNote(noteId: string, req: Request, db: Db): Promise<Response> {
  const user = await authenticate(req, db);
  if (!user) return unauthorized();

  const note = await db.notes.findById(noteId);
  if (!note || note.userId !== user.id) return notFound();

  const body = await readJsonBody(req);
  if (!body) return badRequest("invalid JSON body");

  const patch: NotePatch = {};
  if (body.title !== undefined) {
    if (typeof body.title !== "string") return badRequest("title must be a string");
    patch.title = body.title;
  }
  if (body.body !== undefined) {
    if (typeof body.body !== "string") return badRequest("body must be a string");
    patch.body = body.body;
  }

  const updated = await db.notes.update(noteId, patch);
  if (!updated) return notFound();
  return json(200, updated);
}

async function handleSearchNotes(req: Request, db: Db, url: URL): Promise<Response> {
  const user = await authenticate(req, db);
  if (!user) return unauthorized();

  const q = url.searchParams.get("q");
  if (!isNonEmptyString(q)) return badRequest("q is required");

  const pattern = globToLikePattern(q);
  const rows = await db.query<Note>(
    "SELECT * FROM notes WHERE user_id = ? AND (title LIKE ? ESCAPE '\\' OR body LIKE ? ESCAPE '\\')",
    [user.id, pattern, pattern]
  );
  return json(200, rows);
}

async function handleImportNote(req: Request, db: Db): Promise<Response> {
  const user = await authenticate(req, db);
  if (!user) return unauthorized();

  const body = await readJsonBody(req);
  const noteId = body?.noteId;
  const sourceUrl = body?.url;
  if (!isNonEmptyString(noteId) || !isNonEmptyString(sourceUrl)) {
    return badRequest("noteId and url are required");
  }

  const note = await db.notes.findById(noteId);
  if (!note || note.userId !== user.id) return notFound();

  let parsedUrl: URL;
  try {
    parsedUrl = new URL(sourceUrl);
  } catch {
    return badRequest("url is invalid");
  }
  if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
    return badRequest("only http/https URLs are supported");
  }
  if (isPrivateOrLoopbackHostname(parsedUrl.hostname)) {
    return badRequest("url host is not allowed");
  }

  let response: Response;
  try {
    response = await fetch(parsedUrl, { redirect: "manual" });
  } catch {
    return badRequest("failed to fetch url");
  }
  if (response.type === "opaqueredirect" || (response.status >= 300 && response.status < 400)) {
    return badRequest("url redirects are not allowed");
  }
  if (!response.ok) {
    return badRequest(`failed to fetch url: ${response.status}`);
  }

  const text = await response.text();
  const truncated = text.length > MAX_IMPORT_BYTES ? text.slice(0, MAX_IMPORT_BYTES) : text;

  const updated = await db.notes.update(noteId, { body: truncated });
  if (!updated) return notFound();
  return json(200, updated);
}

/** Builds the fetch-style `handle(req)` entry point with `db` injected via closure. */
export function createHandler(db: Db): (req: Request) => Promise<Response> {
  return async function handle(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const { pathname } = url;
    const method = req.method.toUpperCase();

    if (method === "POST" && pathname === "/signup") {
      return handleSignup(req, db);
    }
    if (method === "POST" && pathname === "/login") {
      return handleLogin(req, db, url);
    }
    if (method === "GET" && pathname === "/notes/search") {
      return handleSearchNotes(req, db, url);
    }

    const noteMatch = /^\/notes\/([^/]+)$/.exec(pathname);
    if (noteMatch) {
      const noteId = decodeURIComponent(noteMatch[1]);
      if (method === "GET") return handleGetNote(noteId, req, db);
      if (method === "PATCH") return handlePatchNote(noteId, req, db);
      return json(405, { error: "method not allowed" });
    }

    if (method === "POST" && pathname === "/notes/import") {
      return handleImportNote(req, db);
    }

    return notFound();
  };
}

