package com.acme.app.feed

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.acme.app.data.FeedRepository
import com.acme.app.data.Post
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.SerializationException
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import java.io.File
import java.io.IOException

data class FeedUiState(
    val posts: List<Post> = emptyList(),
    val isLoading: Boolean = false,
    val error: String? = null,
    val draftText: String = "",
)

/**
 * [cacheDir] holds the persisted draft; [ioDispatcher] defaults to [Dispatchers.IO] but can be
 * swapped for a test dispatcher so draft writes are deterministic under `runTest`.
 */
class FeedViewModel(
    private val repository: FeedRepository,
    cacheDir: File,
    private val ioDispatcher: CoroutineDispatcher = Dispatchers.IO,
) : ViewModel() {

    @Serializable
    private data class DraftDto(val text: String)

    private val draftFile = File(cacheDir, "feed_draft.json")

    private val _uiState = MutableStateFlow(FeedUiState(draftText = readDraft()))
    val uiState: StateFlow<FeedUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            repository.feed().collect { posts ->
                _uiState.update { it.copy(posts = posts) }
            }
        }
        refresh()
    }

    fun refresh() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            try {
                repository.refresh()
                _uiState.update { it.copy(isLoading = false) }
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                _uiState.update { it.copy(isLoading = false, error = e.message ?: "Couldn't refresh the feed") }
            }
        }
    }

    fun toggleLike(postId: String) {
        val post = _uiState.value.posts.firstOrNull { it.id == postId } ?: return
        val originalLiked = post.likedByMe
        val newLiked = !originalLiked
        setLikedLocally(postId, newLiked)
        viewModelScope.launch {
            try {
                repository.setLiked(postId, newLiked)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                setLikedLocally(postId, originalLiked)
                _uiState.update { it.copy(error = e.message ?: "Couldn't update like") }
            }
        }
    }

    fun updateDraft(text: String) {
        _uiState.update { it.copy(draftText = text) }
        viewModelScope.launch(ioDispatcher) {
            writeDraft(text)
        }
    }

    // Guarded by the current `likedByMe` value so a rollback (calling this again with the
    // original value) can't double-apply the like-count delta if it races a server-confirmed update.
    private fun setLikedLocally(postId: String, liked: Boolean) {
        _uiState.update { state ->
            state.copy(
                posts = state.posts.map { post ->
                    if (post.id != postId || post.likedByMe == liked) {
                        post
                    } else {
                        post.copy(likedByMe = liked, likeCount = post.likeCount + if (liked) 1 else -1)
                    }
                },
            )
        }
    }

    private fun readDraft(): String {
        if (!draftFile.isFile) return ""
        return try {
            Json.decodeFromString<DraftDto>(draftFile.readText()).text
        } catch (e: IOException) {
            ""
        } catch (e: SerializationException) {
            ""
        }
    }

    private fun writeDraft(text: String) {
        try {
            draftFile.parentFile?.mkdirs()
            draftFile.writeText(Json.encodeToString(DraftDto(text)))
        } catch (e: IOException) {
            // Draft persistence is best-effort; losing the cached draft is not fatal.
        }
    }
}

package com.acme.app.feed

import com.acme.app.data.FeedRepository
