private class FakeFeedRepository(initialPosts: List<Post> = emptyList()) : FeedRepository {
    private val postsFlow = MutableStateFlow(initialPosts)

    var refreshError: Throwable? = null
    var setLikedError: Throwable? = null
    var refreshCount = 0
    val setLikedCalls = mutableListOf<Pair<String, Boolean>>()

    override fun feed(): Flow<List<Post>> = postsFlow.asStateFlow()

    override suspend fun refresh() {
        refreshCount++
        refreshError?.let { throw it }
    }

    override suspend fun setLiked(postId: String, liked: Boolean) {
        setLikedCalls.add(postId to liked)
        setLikedError?.let { throw it }
        postsFlow.update { posts -> posts.map { if (it.id == postId) it.copy(likedByMe = liked) else it } }
    }
}

class FeedViewModelTest {

    private val dispatcher = StandardTestDispatcher()
    private lateinit var cacheDir: File

    @BeforeTest
    fun setUp() {
        setMain(dispatcher)
        cacheDir = Files.createTempDirectory("feed-viewmodel-test").toFile()
    }

    @AfterTest
    fun tearDown() {
        cacheDir.deleteRecursively()
        resetMain()
    }

    private fun samplePost(id: String = "p1", likeCount: Int = 3, likedByMe: Boolean = false) =
        Post(id = id, authorName = "Ada", text = "hello", likeCount = likeCount, likedByMe = likedByMe)

    @Test
    fun loadsFeedAndRefreshesOnStart() = runTest(dispatcher) {
        val repository = FakeFeedRepository(listOf(samplePost()))
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)

        assertEquals(1, repository.refreshCount)
        assertTrue(viewModel.uiState.value.isLoading)

        dispatcher.scheduler.advanceUntilIdle()

        assertEquals(listOf(samplePost()), viewModel.uiState.value.posts)
        assertEquals(false, viewModel.uiState.value.isLoading)
        assertNull(viewModel.uiState.value.error)
    }

    @Test
    fun refreshSurfacesErrorAndClearsLoading() = runTest(dispatcher) {
        val repository = FakeFeedRepository()
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)
        dispatcher.scheduler.advanceUntilIdle()

        repository.refreshError = IOException("network down")
        viewModel.refresh()
        dispatcher.scheduler.advanceUntilIdle()

        assertEquals(false, viewModel.uiState.value.isLoading)
        assertEquals("network down", viewModel.uiState.value.error)
    }

    @Test
    fun toggleLikeUpdatesUiOptimisticallyBeforeRepositoryResponds() = runTest(dispatcher) {
        val repository = FakeFeedRepository(listOf(samplePost(likeCount = 3, likedByMe = false)))
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)
        dispatcher.scheduler.advanceUntilIdle()

        viewModel.toggleLike("p1")

        val optimisticPost = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertEquals(true, optimisticPost.likedByMe)
        assertEquals(4, optimisticPost.likeCount)

        dispatcher.scheduler.advanceUntilIdle()

        val settledPost = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertEquals(true, settledPost.likedByMe)
        assertEquals(4, settledPost.likeCount)
        assertEquals(listOf("p1" to true), repository.setLikedCalls)
    }

    @Test
    fun toggleLikeRollsBackWhenRepositoryFails() = runTest(dispatcher) {
        val repository = FakeFeedRepository(listOf(samplePost(likeCount = 3, likedByMe = false)))
        repository.setLikedError = IOException("boom")
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)
        dispatcher.scheduler.advanceUntilIdle()

        viewModel.toggleLike("p1")
        assertEquals(true, viewModel.uiState.value.posts.single().likedByMe)

        dispatcher.scheduler.advanceUntilIdle()

        val rolledBackPost = viewModel.uiState.value.posts.single()
        assertEquals(false, rolledBackPost.likedByMe)
        assertEquals(3, rolledBackPost.likeCount)
        assertEquals("boom", viewModel.uiState.value.error)
    }

    @Test
    fun updateDraftPersistsToCacheFileAndIsRestoredByNewViewModel() = runTest(dispatcher) {
        val repository = FakeFeedRepository()
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)
        dispatcher.scheduler.advanceUntilIdle()

        viewModel.updateDraft("draft in progress")
        assertEquals("draft in progress", viewModel.uiState.value.draftText)

        dispatcher.scheduler.advanceUntilIdle()

        val draftFile = File(cacheDir, "feed_draft.json")
        assertTrue(draftFile.isFile)
        assertTrue(draftFile.readText().contains("draft in progress"))

        val restored = FeedViewModel(FakeFeedRepository(), cacheDir, ioDispatcher = dispatcher)
        assertEquals("draft in progress", restored.uiState.value.draftText)
    }

    @Test
    fun missingDraftFileStartsWithEmptyDraft() = runTest(dispatcher) {
        val repository = FakeFeedRepository()
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)

        assertEquals("", viewModel.uiState.value.draftText)
    }

    @Test
    fun toggleLikeOnUnknownPostIsNoOp() = runTest(dispatcher) {
        val repository = FakeFeedRepository(listOf(samplePost()))
        val viewModel = FeedViewModel(repository, cacheDir, ioDispatcher = dispatcher)
        dispatcher.scheduler.advanceUntilIdle()

        viewModel.toggleLike("does-not-exist")
        dispatcher.scheduler.advanceUntilIdle()

        assertEquals(emptyList(), repository.setLikedCalls)
        assertNotNull(viewModel.uiState.value.posts.single { it.id == "p1" })
    }
}

// Notes service HTTP handler. Uses only web-standard APIs (fetch, crypto.subtle, URL).

export interface DbUser {
  id: string;
  email: string;
  passwordHash: string;
  passwordSalt: string;
}

export interface DbNote {
  id: string;
  userId: string;
  title: string;
  body: string;
}

export interface Db {
  users: {
    findByEmail(email: string): Promise<DbUser | null>;
    findById(id: string): Promise<DbUser | null>;
    create(user: DbUser): Promise<void>;
  };
  notes: {
    findById(id: string): Promise<DbNote | null>;
    update(id: string, patch: Partial<Pick<DbNote, "title" | "body">>): Promise<DbNote>;
  };
  // Raw parameterized query escape hatch (e.g. for sessions, full-text search).
  // `params` are bound placeholders (`?`) — never interpolate untrusted input into `sql`.
  query<T = unknown>(sql: string, params?: unknown[]): Promise<T[]>;
}

interface SessionRow {
  token_hash: string;
  user_id: string;
  expires_at: number;
}

const PBKDF2_ITERATIONS = 210_000;
const SALT_BYTES = 16;
const TOKEN_BYTES = 32;
const SESSION_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_IMPORT_BYTES = 1_000_000;
const IMPORT_TIMEOUT_MS = 5_000;
const MAX_SEARCH_RESULTS = 100;

function json(data: unknown, status = 200, extraHeaders?: HeadersInit): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json", ...extraHeaders },
  });
}

function errorResponse(status: number, message: string): Response {
  return json({ error: message }, status);
}

function toHex(bytes: ArrayBuffer | Uint8Array): string {
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  return Array.from(arr, (b) => b.toString(16).padStart(2, "0")).join("");
}

function fromHex(hex: string): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return out;
}

function randomHex(byteLength: number): string {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return toHex(bytes);
}

function constantTimeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

async function derivePasswordHash(password: string, saltHex: string): Promise<string> {
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveBits"],
  );
  const bits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: fromHex(saltHex),
      iterations: PBKDF2_ITERATIONS,
      hash: "SHA-256",
    },
    keyMaterial,
    256,
  );
  return toHex(bits);
}

async function hashSha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input));
  return toHex(digest);
}

async function verifyPassword(password: string, user: DbUser | null): Promise<boolean> {
  // Always derive a hash, even for unknown users, so response timing doesn't
  // reveal whether the email is registered.
  const salt = user?.passwordSalt ?? randomHex(SALT_BYTES);
  const computed = await derivePasswordHash(password, salt);
  if (!user) return false;
  return constantTimeEqual(fromHex(computed), fromHex(user.passwordHash));
}

function isValidEmail(email: unknown): email is string {
  return typeof email === "string" && email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidPassword(password: unknown): password is string {
  return typeof password === "string" && password.length >= 8 && password.length <= 1024;
}

// Only allow same-origin relative paths for post-login redirects, to prevent
// open-redirect attacks via a crafted `next` value (e.g. "https://evil.example").
function sanitizeNextPath(next: string | null): string {
  const fallback = "/";
  if (!next) return fallback;
  if (!next.startsWith("/") || next.startsWith("//") || next.startsWith("/\\")) return fallback;
  try {
    // Resolving against a dummy origin rejects values containing an embedded
    // scheme/host (e.g. "/\t/evil.example" tricks some parsers).
    const resolved = new URL(next, "http://localhost");
    if (resolved.origin !== "http://localhost") return fallback;
    return resolved.pathname + resolved.search + resolved.hash;
  } catch {
    return fallback;
  }
}

const PRIVATE_HOSTNAMES = new Set(["localhost", "127.0.0.1", "::1", "0.0.0.0"]);

function isPrivateIpv4(hostname: string): boolean {
  const parts = hostname.split(".").map(Number);
  if (parts.length !== 4 || parts.some((p) => Number.isNaN(p) || p < 0 || p > 255)) return false;
  const [firstOctet, secondOctet] = parts;
  if (firstOctet === 10) return true;
  if (firstOctet === 127) return true;
  if (firstOctet === 169 && secondOctet === 254) return true;
  if (firstOctet === 172 && secondOctet >= 16 && secondOctet <= 31) return true;
  if (firstOctet === 192 && secondOctet === 168) return true;
  if (firstOctet === 0) return true;
  return false;
}

// Best-effort SSRF guard: only http(s), no credentials in the URL, and no
// obviously-internal hostname/IP literal. DNS can still resolve a public
// hostname to a private address; callers should pair this with network-level
// egress controls for full protection.
function isSafeImportUrl(rawUrl: string): URL | null {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    return null;
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") return null;
  if (url.username || url.password) return null;
  const hostname = url.hostname.toLowerCase();
  if (PRIVATE_HOSTNAMES.has(hostname)) return null;
  if (hostname.endsWith(".local") || hostname.endsWith(".internal")) return null;
  if (isPrivateIpv4(hostname)) return null;
  if (hostname.startsWith("[") || hostname.includes(":")) return null; // reject IPv6 literals outright
  return url;
}

// Escapes SQL LIKE metacharacters, then maps our simple wildcard syntax
// ('*' = any run of characters, '?' = any single character) onto LIKE's.
function wildcardToLikePattern(q: string): string {
  let out = "";
  for (const ch of q) {
    if (ch === "%" || ch === "_" || ch === "\\") {
      out += "\\" + ch;
    } else if (ch === "*") {
      out += "%";
    } else if (ch === "?") {
      out += "_";
    } else {
      out += ch;
    }
  }
  return out;
}

function getCookie(req: Request, name: string): string | null {
  const header = req.headers.get("cookie");
  if (!header) return null;
  for (const part of header.split(";")) {
    const idx = part.indexOf("=");
    if (idx === -1) continue;
    const key = part.slice(0, idx).trim();
    if (key === name) return decodeURIComponent(part.slice(idx + 1).trim());
  }
  return null;
}

function getBearerToken(req: Request): string | null {
  const header = req.headers.get("authorization");
  if (!header) return null;
  const match = /^Bearer\s+(.+)$/i.exec(header);
  return match ? match[1].trim() : null;
}

async function readJsonBody(req: Request): Promise<unknown> {
  try {
    return await req.json();
  } catch {
    return null;
  }
}

export class NotesApi {
  constructor(private readonly db: Db) {}

  async handle(req: Request): Promise<Response> {
    const url = new URL(req.url);
    const path = url.pathname;

    try {
      if (req.method === "POST" && path === "/signup") return this.signup(req);
      if (req.method === "POST" && path === "/login") return this.login(req, url);
      if (req.method === "GET" && path === "/notes/search") return this.searchNotes(req, url);
      if (req.method === "POST" && path === "/notes/import") return this.importNote(req);

      const noteMatch = /^\/notes\/([^/]+)$/.exec(path);
      if (noteMatch) {
        const noteId = decodeURIComponent(noteMatch[1]);
        if (req.method === "GET") return this.getNote(req, noteId);
        if (req.method === "PATCH") return this.patchNote(req, noteId);
        return errorResponse(405, "Method not allowed");
      }

      return errorResponse(404, "Not found");
    } catch (err) {
      console.error("Unhandled error in notes API", err);
      return errorResponse(500, "Internal server error");
    }
  }

  private async requireSession(req: Request): Promise<DbUser | null> {
    const token = getBearerToken(req) ?? getCookie(req, "session");
    if (!token) return null;
    const tokenHash = await hashSha256Hex(token);
    const rows = await this.db.query<SessionRow>(
      "SELECT token_hash, user_id, expires_at FROM sessions WHERE token_hash = ?",
      [tokenHash],
    );
    const session = rows[0];
    if (!session || session.expires_at < Date.now()) return null;
    return this.db.users.findById(session.user_id);
  }

  private async signup(req: Request): Promise<Response> {
    const body = await readJsonBody(req);
    if (typeof body !== "object" || body === null) return errorResponse(400, "Invalid request body");
    const { email, password } = body as Record<string, unknown>;
    if (!isValidEmail(email)) return errorResponse(400, "Invalid email");
    if (!isValidPassword(password)) return errorResponse(400, "Password must be 8-1024 characters");

    const existing = await this.db.users.findByEmail(email);
    if (existing) return errorResponse(409, "Email already registered");

    const passwordSalt = randomHex(SALT_BYTES);
    const passwordHash = await derivePasswordHash(password, passwordSalt);
    const user: DbUser = { id: crypto.randomUUID(), email, passwordHash, passwordSalt };
    await this.db.users.create(user);

    return json({ id: user.id, email: user.email }, 201);
  }

  private async login(req: Request, url: URL): Promise<Response> {
    const body = await readJsonBody(req);
    if (typeof body !== "object" || body === null) return errorResponse(400, "Invalid request body");
    const { email, password } = body as Record<string, unknown>;
    if (typeof email !== "string" || typeof password !== "string") {
      return errorResponse(400, "Invalid credentials");
    }

    const user = await this.db.users.findByEmail(email);
    const valid = await verifyPassword(password, user);
    if (!valid || !user) return errorResponse(401, "Invalid email or password");

    const token = randomHex(TOKEN_BYTES);
    const tokenHash = await hashSha256Hex(token);
    const expiresAt = Date.now() + SESSION_TTL_MS;
    await this.db.query("INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, ?)", [
      tokenHash,
      user.id,
      expiresAt,
    ]);

    const nextPath = sanitizeNextPath(url.searchParams.get("next"));
    return new Response(null, {
      status: 303,
      headers: {
        location: nextPath,
        "set-cookie": `session=${token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${Math.floor(
          SESSION_TTL_MS / 1000,
        )}`,
      },
    });
  }

  private async getNote(req: Request, noteId: string): Promise<Response> {
    const user = await this.requireSession(req);
    if (!user) return errorResponse(401, "Not authenticated");

    const note = await this.db.notes.findById(noteId);
    if (!note || note.userId !== user.id) return errorResponse(404, "Note not found");
    return json(note);
  }

  private async patchNote(req: Request, noteId: string): Promise<Response> {
    const user = await this.requireSession(req);
    if (!user) return errorResponse(401, "Not authenticated");

    const note = await this.db.notes.findById(noteId);
    if (!note || note.userId !== user.id) return errorResponse(404, "Note not found");

    const body = await readJsonBody(req);
    if (typeof body !== "object" || body === null) return errorResponse(400, "Invalid request body");
    const { title, body: noteBody } = body as Record<string, unknown>;

    const patch: Partial<Pick<DbNote, "title" | "body">> = {};
    if (title !== undefined) {
      if (typeof title !== "string") return errorResponse(400, "title must be a string");
      patch.title = title;
    }
    if (noteBody !== undefined) {
      if (typeof noteBody !== "string") return errorResponse(400, "body must be a string");
      patch.body = noteBody;
    }

    const updated = await this.db.notes.update(noteId, patch);
    return json(updated);
  }

  private async searchNotes(req: Request, url: URL): Promise<Response> {
    const user = await this.requireSession(req);
    if (!user) return errorResponse(401, "Not authenticated");

    const q = url.searchParams.get("q");
    if (!q) return errorResponse(400, "Missing q parameter");

    const pattern = wildcardToLikePattern(q);
    const rows = await this.db.query<DbNote>(
      "SELECT * FROM notes WHERE user_id = ? AND (title LIKE ? ESCAPE '\\' OR body LIKE ? ESCAPE '\\') LIMIT ?",
      [user.id, pattern, pattern, MAX_SEARCH_RESULTS],
    );
    return json(rows);
  }

  private async importNote(req: Request): Promise<Response> {
    const user = await this.requireSession(req);
    if (!user) return errorResponse(401, "Not authenticated");

    const body = await readJsonBody(req);
    if (typeof body !== "object" || body === null) return errorResponse(400, "Invalid request body");
    const { noteId, url: importUrl } = body as Record<string, unknown>;
    if (typeof noteId !== "string" || typeof importUrl !== "string") {
      return errorResponse(400, "noteId and url are required");
    }

    const note = await this.db.notes.findById(noteId);
    if (!note || note.userId !== user.id) return errorResponse(404, "Note not found");

    const safeUrl = isSafeImportUrl(importUrl);
    if (!safeUrl) return errorResponse(400, "url is not permitted");

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), IMPORT_TIMEOUT_MS);
    let text: string;
    try {
      const res = await fetch(safeUrl, { redirect: "manual", signal: controller.signal });
      if (res.type === "opaqueredirect" || (res.status >= 300 && res.status < 400)) {
        return errorResponse(400, "Redirects are not allowed for imports");
      }
      if (!res.ok) return errorResponse(400, `Failed to download note (status ${res.status})`);

      const contentLength = res.headers.get("content-length");
      if (contentLength && Number(contentLength) > MAX_IMPORT_BYTES) {
        return errorResponse(400, "Remote content is too large");
      }

      text = await this.readLimitedText(res);
    } catch (err) {
      if (err instanceof Error && err.name === "AbortError") {
        return errorResponse(504, "Timed out downloading note");
      }
      return errorResponse(502, "Failed to fetch note content");
    } finally {
      clearTimeout(timeout);
    }

    const updated = await this.db.notes.update(noteId, { body: text });
    return json(updated);
  }

  private async readLimitedText(res: Response): Promise<string> {
    if (!res.body) return "";
    const reader = res.body.getReader();
    const chunks: Uint8Array[] = [];
    let total = 0;
    try {
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        total += value.byteLength;
        if (total > MAX_IMPORT_BYTES) {
          throw new Error("Remote content exceeded size limit");
        }
        chunks.push(value);
      }
    } finally {
      reader.releaseLock();
    }
    const combined = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
      combined.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return new TextDecoder().decode(combined);
  }
}

