import logging
from collections.abc import Callable

import requests
from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from starlette.concurrency import run_in_threadpool

from app.auth import get_current_user
from app.clients.payments import PaymentsClient
from app.db import get_db
from app.models import Order, User
from app.notifications import send_email

logger = logging.getLogger(__name__)

router = APIRouter(prefix="/orders", tags=["orders"])


def get_payments_client() -> PaymentsClient:
    return PaymentsClient()


def get_notifier() -> Callable[[str, str, str], None]:
    return send_email


def _serialize_order(order: Order) -> dict:
    return {
        "id": order.id,
        "status": order.status,
        "total": float(order.total),
        "payment_id": order.payment_id,
        "items": [
            {
                "id": item.id,
                "product_id": item.product_id,
                "quantity": item.quantity,
            }
            for item in order.items
        ],
    }


def _get_owned_order(db: Session, order_id: int, user: User) -> Order:
    order = db.get(Order, order_id)
    if order is None or order.user_id != user.id:
        raise HTTPException(status_code=404, detail="order not found")
    return order


@router.get("/{order_id}")
async def get_order(
    order_id: int,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
) -> dict:
    order = _get_owned_order(db, order_id, user)
    return _serialize_order(order)


@router.post("/{order_id}/refund")
async def refund_order(
    order_id: int,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
    payments: PaymentsClient = Depends(get_payments_client),
    notify: Callable[[str, str, str], None] = Depends(get_notifier),
) -> dict:
    order = _get_owned_order(db, order_id, user)

    if order.status == "refunded":
        raise HTTPException(status_code=409, detail="order already refunded")

    if not order.payment_id:
        raise HTTPException(status_code=400, detail="order has no associated payment")

    try:
        await run_in_threadpool(payments.refund, order.payment_id, float(order.total))
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail="payment provider error") from exc

    order.status = "refunded"
    db.commit()
    db.refresh(order)

    try:
        await run_in_threadpool(
            notify,
            user.email,
            "Your refund has been processed",
            f"Order #{order.id} for {order.total} has been refunded.",
        )
    except Exception:
        logger.exception("failed to send refund receipt for order %s", order.id)

    return _serialize_order(order)

"""Thin wrapper over the payments provider's official Python SDK (synchronous, uses requests)."""

import os
from dataclasses import dataclass
from functools import lru_cache

import requests


@dataclass
class Refund:
    id: str
    status: str


class PaymentsClient:
    def __init__(self, api_key: str | None = None, base_url: str = "https://api.payments.example.com/v1"):
        self.api_key = api_key or os.environ["PAYMENTS_API_KEY"]
        self.base_url = base_url
        self.session = requests.Session()
        self.session.headers["Authorization"] = f"Bearer {self.api_key}"

    def refund(self, payment_id: str, amount: float) -> Refund:
        resp = self.session.post(f"{self.base_url}/refunds", json={"payment": payment_id, "amount": amount}, timeout=10)
        resp.raise_for_status()
        data = resp.json()
        return Refund(id=data["id"], status=data["status"])

    def get_payment(self, payment_id: str) -> dict:
        resp = self.session.get(f"{self.base_url}/payments/{payment_id}", timeout=10)
        resp.raise_for_status()
        return resp.json()


@lru_cache
def get_payments_client() -> PaymentsClient:
    return PaymentsClient()

