import asyncio
import hashlib
import hmac
import ipaddress
import json
import os
import socket
from html.parser import HTMLParser
from urllib.parse import urlparse

import httpx
from fastapi import APIRouter, Depends, Header, HTTPException, Query, Request
from sqlalchemy.orm import Session

from app.db import get_db
from app.models import Order

router = APIRouter()

WEBHOOK_STATUS_BY_EVENT = {
    "payment.succeeded": "paid",
    "payment.failed": "failed",
}

MAX_PREVIEW_BYTES = 2_000_000
FETCH_TIMEOUT_SECONDS = 5.0


@router.post("/webhooks/payments")
async def payments_webhook(
    request: Request,
    x_signature: str = Header(...),
    db: Session = Depends(get_db),
) -> dict[str, str]:
    secret = os.environ.get("PAYMENTS_WEBHOOK_SECRET")
    if not secret:
        raise HTTPException(status_code=500, detail="webhook secret is not configured")

    raw_body = await request.body()
    expected_signature = hmac.new(secret.encode(), raw_body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_signature, x_signature.strip().lower()):
        raise HTTPException(status_code=401, detail="invalid signature")

    try:
        payload = json.loads(raw_body)
    except json.JSONDecodeError as exc:
        raise HTTPException(status_code=400, detail="invalid json body") from exc

    event = payload.get("event")
    payment_id = payload.get("payment_id")
    new_status = WEBHOOK_STATUS_BY_EVENT.get(event)
    if new_status is None or not payment_id:
        raise HTTPException(status_code=400, detail="unsupported or incomplete payload")

    updated = await asyncio.to_thread(_apply_payment_status, db, payment_id, new_status)
    if not updated:
        raise HTTPException(status_code=404, detail="no order matches this payment")

    return {"status": "ok"}


def _apply_payment_status(db: Session, payment_id: str, new_status: str) -> bool:
    order = db.query(Order).filter(Order.payment_id == payment_id).first()
    if order is None:
        return False
    order.status = new_status
    db.commit()
    return True


def _is_public_host(hostname: str) -> bool:
    try:
        infos = socket.getaddrinfo(hostname, None)
    except socket.gaierror:
        return False

    if not infos:
        return False

    for info in infos:
        ip = ipaddress.ip_address(info[4][0])
        if (
            ip.is_private
            or ip.is_loopback
            or ip.is_link_local
            or ip.is_reserved
            or ip.is_multicast
            or ip.is_unspecified
        ):
            return False
    return True


async def _fetch_page(url: str) -> httpx.Response:
    async with httpx.AsyncClient(follow_redirects=False, timeout=FETCH_TIMEOUT_SECONDS) as client:
        return await client.get(url)


class _PreviewParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.title: str | None = None
        self.description: str | None = None
        self._in_title = False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "title":
            self._in_title = True
        elif tag == "meta" and self.description is None:
            attrs_dict = {k.lower(): v for k, v in attrs}
            name = (attrs_dict.get("name") or attrs_dict.get("property") or "").lower()
            if name in ("description", "og:description"):
                self.description = attrs_dict.get("content")

    def handle_endtag(self, tag: str) -> None:
        if tag == "title":
            self._in_title = False

    def handle_data(self, data: str) -> None:
        if self._in_title and self.title is None:
            self.title = data.strip()


@router.get("/link-preview")
async def link_preview(url: str = Query(...)) -> dict[str, str | None]:
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.hostname:
        raise HTTPException(status_code=400, detail="url must be an absolute http(s) url")

    is_public = await asyncio.to_thread(_is_public_host, parsed.hostname)
    if not is_public:
        raise HTTPException(status_code=400, detail="url is not allowed")

    try:
        response = await _fetch_page(url)
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail="failed to fetch url") from exc

    if response.is_redirect or response.status_code >= 400:
        raise HTTPException(status_code=502, detail="failed to fetch url")

    content_type = response.headers.get("content-type", "")
    if content_type and "html" not in content_type:
        raise HTTPException(status_code=400, detail="url did not return an html page")

    parser = _PreviewParser()
    parser.feed(response.text[:MAX_PREVIEW_BYTES])

    return {"url": url, "title": parser.title, "description": parser.description}

