import hashlib
import hmac
import ipaddress
import os
import socket
from html.parser import HTMLParser
from typing import Literal
from urllib.parse import urljoin, urlparse

import httpx
from fastapi import APIRouter, Depends, Header, HTTPException, Query, Request, Response
from pydantic import BaseModel
from sqlalchemy.orm import Session

from app.db import get_db
from app.models import Order

router = APIRouter()

MAX_REDIRECTS = 5
MAX_PREVIEW_BYTES = 2 * 1024 * 1024


class PaymentWebhookPayload(BaseModel):
    order_id: int
    payment_id: str
    status: Literal["succeeded", "failed"]


def _verify_signature(body: bytes, signature: str) -> bool:
    secret = os.environ.get("PAYMENTS_WEBHOOK_SECRET")
    if not secret:
        raise HTTPException(status_code=500, detail="webhook secret not configured")
    expected = hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


@router.post("/webhooks/payments", status_code=204)
async def payments_webhook(
    request: Request,
    x_signature: str = Header(..., alias="X-Signature"),
    db: Session = Depends(get_db),
) -> Response:
    body = await request.body()
    if not _verify_signature(body, x_signature):
        raise HTTPException(status_code=401, detail="invalid signature")

    payload = PaymentWebhookPayload.model_validate_json(body)

    order = db.get(Order, payload.order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")

    order.status = "paid" if payload.status == "succeeded" else "failed"
    order.payment_id = payload.payment_id
    db.commit()
    return Response(status_code=204)


def _ensure_public_http_url(url: str) -> None:
    """Reject anything but http(s) URLs that resolve to public IP addresses, to guard against SSRF."""
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        raise HTTPException(status_code=400, detail="only http/https urls are allowed")
    hostname = parsed.hostname
    if not hostname:
        raise HTTPException(status_code=400, detail="url must include a hostname")
    try:
        resolved = socket.getaddrinfo(hostname, parsed.port or (443 if parsed.scheme == "https" else 80))
    except socket.gaierror as exc:
        raise HTTPException(status_code=400, detail="could not resolve host") from exc
    for *_, sockaddr in resolved:
        ip = ipaddress.ip_address(sockaddr[0])
        if not ip.is_global:
            raise HTTPException(status_code=400, detail="url resolves to a disallowed address")


def _fetch_html(url: str) -> str:
    for _ in range(MAX_REDIRECTS):
        _ensure_public_http_url(url)
        with httpx.Client(timeout=5.0) as client, client.stream(
            "GET", url, follow_redirects=False, headers={"User-Agent": "shop-api-link-preview/1.0"}
        ) as resp:
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("location")
                if not location:
                    raise HTTPException(status_code=502, detail="redirect missing location")
                url = urljoin(url, location)
                continue
            if resp.status_code >= 400:
                raise HTTPException(status_code=502, detail="failed to fetch url")
            content_type = resp.headers.get("content-type", "")
            if "html" not in content_type.lower():
                raise HTTPException(status_code=415, detail="url did not return html")
            chunks: list[bytes] = []
            total = 0
            for chunk in resp.iter_bytes():
                total += len(chunk)
                if total > MAX_PREVIEW_BYTES:
                    break
                chunks.append(chunk)
            return b"".join(chunks).decode(resp.encoding or "utf-8", errors="replace")
    raise HTTPException(status_code=502, detail="too many redirects")


class _PreviewParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.title: str | None = None
        self.description: str | None = None
        self._in_title = False

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag == "title":
            self._in_title = True
        elif tag == "meta":
            attrs_dict = {key.lower(): value for key, value in attrs if key}
            name = (attrs_dict.get("name") or attrs_dict.get("property") or "").lower()
            if name in ("description", "og:description") and self.description is None:
                self.description = attrs_dict.get("content")

    def handle_endtag(self, tag: str) -> None:
        if tag == "title":
            self._in_title = False

    def handle_data(self, data: str) -> None:
        if self._in_title and self.title is None:
            self.title = data.strip()


@router.get("/link-preview")
def link_preview(url: str = Query(...)) -> dict[str, str | None]:
    html = _fetch_html(url)
    parser = _PreviewParser()
    parser.feed(html)
    return {"title": parser.title, "description": parser.description}

package com.acme.app.sync

import com.acme.app.data.Account
import com.acme.app.data.AccountApi
import java.io.File
import java.time.Instant
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.serialization.builtins.MapSerializer
import kotlinx.serialization.builtins.serializer
import kotlinx.serialization.json.Json
import kotlin.time.Duration
import kotlin.time.Duration.Companion.minutes

/** Progress of an in-flight [SyncManager.sync] run. */
data class SyncProgress(
    val accountsDone: Int,
    val totalAccounts: Int,
    val currentAccount: Account?,
)

/** Last-known outcome of a sync, for the UI to observe. */
data class SyncStatus(
    val lastSyncTime: Instant? = null,
    val lastError: String? = null,
)

/** Holds the most recent sync outcome for the UI to observe. */
class SyncStatusStore {
    private val _status = MutableStateFlow(SyncStatus())
    val status: StateFlow<SyncStatus> = _status.asStateFlow()

    fun recordSuccess(time: Instant = Instant.now()) {
        _status.value = SyncStatus(lastSyncTime = time, lastError = null)
    }

    fun recordError(message: String) {
        _status.value = _status.value.copy(lastError = message)
    }
}

/**
 * Persists each account's last-seen cursor to [file] as JSON, so a sync can resume
 * where the previous one left off instead of re-fetching everything.
 */
private class CursorStore(private val file: File) {
    private val json = Json { ignoreUnknownKeys = true }
    private val serializer = MapSerializer(String.serializer(), String.serializer())

    fun load(): MutableMap<String, String> {
        if (!file.exists()) return mutableMapOf()
        return runCatching { json.decodeFromString(serializer, file.readText()) }
            .getOrDefault(emptyMap())
            .toMutableMap()
    }

    fun save(cursors: Map<String, String>) {
        file.parentFile?.mkdirs()
        file.writeText(json.encodeToString(serializer, cursors))
    }
}

/**
 * Syncs every account by paging through [AccountApi.changesSince] until each one runs out
 * of pages, resuming from the last cursor stored in [cursorFile] on the following run.
 */
class SyncManager(
    private val accountApi: AccountApi,
    private val statusStore: SyncStatusStore,
    cursorFile: File,
) {
    private val cursorStore = CursorStore(cursorFile)

    fun sync(): Flow<SyncProgress> = flow {
        val accounts = accountApi.accounts()
        val cursors = cursorStore.load()
        try {
            for ((index, account) in accounts.withIndex()) {
                emit(SyncProgress(accountsDone = index, totalAccounts = accounts.size, currentAccount = account))

                var cursor = cursors[account.id]
                while (true) {
                    val page = accountApi.changesSince(account.id, cursor)
                    cursor = page.nextCursor
                    if (cursor == null) break
                    cursors[account.id] = cursor
                    cursorStore.save(cursors)
                }
            }
            emit(SyncProgress(accountsDone = accounts.size, totalAccounts = accounts.size, currentAccount = null))
            statusStore.recordSuccess()
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            statusStore.recordError(e.message ?: "Sync failed")
            throw e
        }
    }

    /** Runs [sync] immediately, then every [interval], until [scope] is cancelled. */
    fun startPeriodicSync(scope: CoroutineScope, interval: Duration = 15.minutes): Job = scope.launch {
        while (isActive) {
            try {
                sync().collect()
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                // Already recorded on statusStore; keep the periodic loop alive.
            }
            delay(interval)
        }
    }
}

