private class FakeAccountApi(
    private val accounts: List<Account>,
    /** accountId -> ordered list of pages returned on successive calls. */
    private val pagesByAccount: Map<String, List<ChangePage>>,
) : AccountApi {
    val callsByAccount = mutableMapOf<String, MutableList<String?>>()
    private val nextPageIndex = mutableMapOf<String, Int>()

    override suspend fun accounts(): List<Account> = accounts

    override suspend fun changesSince(accountId: String, cursor: String?): ChangePage {
        callsByAccount.getOrPut(accountId) { mutableListOf() }.add(cursor)
        val pages = pagesByAccount.getValue(accountId)
        val index = nextPageIndex.getOrDefault(accountId, 0)
        nextPageIndex[accountId] = index + 1
        return pages[index]
    }
}

private fun tempCursorFile(): File = File.createTempFile("cursors", ".json").apply { deleteOnExit() }

class SyncManagerTest {
    private val accountA = Account("a", "Ada")
    private val accountB = Account("b", "Bob")

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun pagesThroughEachAccountUntilNoNextCursor() = runTest {
        val api = FakeAccountApi(
            accounts = listOf(accountA, accountB),
            pagesByAccount = mapOf(
                "a" to listOf(
                    ChangePage(items = listOf("a1"), nextCursor = "c1"),
                    ChangePage(items = listOf("a2"), nextCursor = "c2"),
                    ChangePage(items = emptyList(), nextCursor = null),
                ),
                "b" to listOf(
                    ChangePage(items = listOf("b1"), nextCursor = null),
                ),
            ),
        )
        val manager = SyncManager(api, SyncStatusStore(), tempCursorFile())

        manager.sync().toList()

        assertEquals(listOf(null, "c1", "c2"), api.callsByAccount.getValue("a"))
        assertEquals(listOf(null), api.callsByAccount.getValue("b"))
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun emitsProgressForEachAccount() = runTest {
        val api = FakeAccountApi(
            accounts = listOf(accountA, accountB),
            pagesByAccount = mapOf(
                "a" to listOf(ChangePage(emptyList(), nextCursor = null)),
                "b" to listOf(ChangePage(emptyList(), nextCursor = null)),
            ),
        )
        val manager = SyncManager(api, SyncStatusStore(), tempCursorFile())

        val progress = manager.sync().toList()

        assertEquals(
            listOf(
                SyncProgress(0, 2, accountA),
                SyncProgress(1, 2, accountB),
                SyncProgress(2, 2, null),
            ),
            progress,
        )
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun persistsCursorToFileAndResumesNextSync() = runTest {
        val cursorFile = tempCursorFile()
        val api = FakeAccountApi(
            accounts = listOf(accountA),
            pagesByAccount = mapOf(
                "a" to listOf(
                    ChangePage(items = listOf("a1"), nextCursor = "c1"),
                    ChangePage(items = emptyList(), nextCursor = null),
                ),
            ),
        )
        SyncManager(api, SyncStatusStore(), cursorFile).sync().toList()

        val stored = Json.parseToJsonElement(cursorFile.readText()).jsonObject
        assertEquals("c1", stored.getValue("a").jsonPrimitive.content)

        val api2 = FakeAccountApi(
            accounts = listOf(accountA),
            pagesByAccount = mapOf("a" to listOf(ChangePage(items = emptyList(), nextCursor = null))),
        )
        SyncManager(api2, SyncStatusStore(), cursorFile).sync().toList()

        assertEquals(listOf("c1"), api2.callsByAccount.getValue("a"))
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun recordsSuccessOnStatusStore() = runTest {
        val api = FakeAccountApi(
            accounts = listOf(accountA),
            pagesByAccount = mapOf("a" to listOf(ChangePage(emptyList(), nextCursor = null))),
        )
        val statusStore = SyncStatusStore()
        SyncManager(api, statusStore, tempCursorFile()).sync().toList()

        val status = statusStore.status.value
        assertTrue(status.lastSyncTime != null)
        assertNull(status.lastError)
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun recordsErrorOnStatusStoreAndPropagatesFailure() = runTest {
        val api = object : AccountApi {
            override suspend fun accounts(): List<Account> = listOf(accountA)
            override suspend fun changesSince(accountId: String, cursor: String?): ChangePage {
                throw IllegalStateException("boom")
            }
        }
        val statusStore = SyncStatusStore()
        val manager = SyncManager(api, statusStore, tempCursorFile())

        var threw = false
        try {
            manager.sync().toList()
        } catch (e: IllegalStateException) {
            threw = true
        }

        assertTrue(threw)
        assertEquals("boom", statusStore.status.value.lastError)
        assertNull(statusStore.status.value.lastSyncTime)
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun periodicSyncRunsImmediatelyThenEveryInterval() = runTest {
        val api = FakeAccountApi(
            accounts = listOf(accountA),
            pagesByAccount = mapOf(
                "a" to List(10) { ChangePage(emptyList(), nextCursor = null) },
            ),
        )
        val statusStore = SyncStatusStore()
        val manager = SyncManager(api, statusStore, tempCursorFile())

        val job = manager.startPeriodicSync(scope = this, interval = 15.minutes)

        advanceTimeBy(1)
        assertEquals(1, api.callsByAccount.getValue("a").size)

        advanceTimeBy(15.minutes)
        assertEquals(2, api.callsByAccount.getValue("a").size)

        advanceTimeBy(15.minutes)
        assertEquals(3, api.callsByAccount.getValue("a").size)

        job.cancel()
    }
}

