import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put

data class FeedUiState(
    val posts: List<Post> = emptyList(),
    val isLoading: Boolean = false,
    val error: String? = null,
    val draftText: String = "",
)

/**
 * ViewModel backing the feed screen.
 *
 * @param cacheDir directory the draft post is persisted to, e.g. `context.cacheDir` on Android.
 */
class FeedViewModel(
    private val repository: FeedRepository,
    private val cacheDir: File,
    private val ioDispatcher: CoroutineDispatcher = Dispatchers.IO,
) : ViewModel() {

    private val _uiState = MutableStateFlow(FeedUiState())
    val uiState: StateFlow<FeedUiState> = _uiState.asStateFlow()

    private val draftFile = File(cacheDir, "feed_draft.json")
    private var draftSaveJob: Job? = null

    init {
        repository.feed()
            .onEach { posts -> _uiState.update { it.copy(posts = posts) } }
            .launchIn(viewModelScope)
        restoreDraft()
    }

    /** Triggered by pull-to-refresh (or an initial load) on the feed screen. */
    fun refresh() {
        viewModelScope.launch {
            _uiState.update { it.copy(isLoading = true, error = null) }
            try {
                repository.refresh()
                _uiState.update { it.copy(isLoading = false) }
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                _uiState.update { it.copy(isLoading = false, error = e.message ?: "Couldn't refresh the feed") }
            }
        }
    }

    /** Flips the like state immediately, then rolls back if persisting it fails. */
    fun toggleLike(postId: String) {
        val previous = _uiState.value.posts.find { it.id == postId } ?: return
        val optimistic = previous.copy(
            likedByMe = !previous.likedByMe,
            likeCount = previous.likeCount + if (previous.likedByMe) -1 else 1,
        )
        replacePost(optimistic)
        viewModelScope.launch {
            try {
                repository.setLiked(postId, optimistic.likedByMe)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                replacePost(previous)
                _uiState.update { it.copy(error = e.message ?: "Couldn't update the like") }
            }
        }
    }

    /** Updates the draft in memory and persists it to [cacheDir], superseding any pending save. */
    fun updateDraft(text: String) {
        _uiState.update { it.copy(draftText = text) }
        draftSaveJob?.cancel()
        draftSaveJob = viewModelScope.launch(ioDispatcher) { saveDraft(text) }
    }

    private fun replacePost(post: Post) {
        _uiState.update { state ->
            state.copy(posts = state.posts.map { if (it.id == post.id) post else it })
        }
    }

    private fun restoreDraft() {
        viewModelScope.launch(ioDispatcher) {
            val text = readDraft()
            _uiState.update { it.copy(draftText = text) }
        }
    }

    private fun readDraft(): String = try {
        if (draftFile.exists()) {
            Json.parseToJsonElement(draftFile.readText())
                .jsonObject["text"]
                ?.jsonPrimitive
                ?.contentOrNull
                ?: ""
        } else {
            ""
        }
    } catch (e: IOException) {
        ""
    } catch (e: SerializationException) {
        ""
    }

    private fun saveDraft(text: String) {
        try {
            cacheDir.mkdirs()
            draftFile.writeText(buildJsonObject { put("text", text) }.toString())
        } catch (e: IOException) {
            // Best-effort persistence: the draft stays in uiState for this session even if the write fails.
        }
    }
}

