import kotlinx.serialization.decodeFromString
import kotlinx.serialization.json.Json

data class FeedUiState(
    val posts: List<Post> = emptyList(),
    val isRefreshing: Boolean = false,
    val error: String? = null,
    val draftText: String = "",
)

@Serializable
private data class DraftDto(val text: String)

class FeedViewModel(
    private val repository: FeedRepository,
    private val draftCacheDir: File,
    private val ioDispatcher: CoroutineDispatcher = Dispatchers.IO,
) : ViewModel() {

    private val draftFile = File(draftCacheDir, "feed_draft.json")

    private val _uiState = MutableStateFlow(FeedUiState())
    val uiState: StateFlow<FeedUiState> = _uiState.asStateFlow()

    init {
        loadDraft()
        viewModelScope.launch {
            repository.feed().collect { posts ->
                _uiState.update { it.copy(posts = posts) }
            }
        }
        refresh()
    }

    fun refresh() {
        viewModelScope.launch {
            _uiState.update { it.copy(isRefreshing = true, error = null) }
            try {
                repository.refresh()
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                _uiState.update { it.copy(error = e.message ?: "Failed to refresh feed") }
            } finally {
                _uiState.update { it.copy(isRefreshing = false) }
            }
        }
    }

    fun toggleLike(postId: String) {
        val previouslyLiked = _uiState.value.posts.find { it.id == postId }?.likedByMe ?: return
        val newLiked = !previouslyLiked
        applyLikeLocally(postId, newLiked)

        viewModelScope.launch {
            try {
                repository.setLiked(postId, newLiked)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                applyLikeLocally(postId, previouslyLiked)
                _uiState.update { it.copy(error = e.message ?: "Failed to update like") }
            }
        }
    }

    fun updateDraft(text: String) {
        _uiState.update { it.copy(draftText = text) }
        saveDraft(text)
    }

    fun clearError() {
        _uiState.update { it.copy(error = null) }
    }

    private fun applyLikeLocally(postId: String, liked: Boolean) {
        _uiState.update { state ->
            state.copy(
                posts = state.posts.map { post ->
                    if (post.id != postId) {
                        post
                    } else {
                        post.copy(
                            likedByMe = liked,
                            likeCount = post.likeCount + if (liked) 1 else -1,
                        )
                    }
                },
            )
        }
    }

    private fun loadDraft() {
        viewModelScope.launch {
            val text = withContext(ioDispatcher) {
                try {
                    if (draftFile.exists()) Json.decodeFromString<DraftDto>(draftFile.readText()).text else null
                } catch (e: CancellationException) {
                    throw e
                } catch (e: Exception) {
                    null
                }
            }
            if (text != null) {
                _uiState.update { it.copy(draftText = text) }
            }
        }
    }

    private fun saveDraft(text: String) {
        viewModelScope.launch {
            withContext(ioDispatcher) {
                try {
                    draftCacheDir.mkdirs()
                    draftFile.writeText(Json.encodeToString(DraftDto(text)))
                } catch (e: CancellationException) {
                    throw e
                } catch (e: Exception) {
                    // Draft persistence is best-effort; losing it isn't fatal.
                }
            }
        }
    }
}

