private class FakeFeedRepository(
    initialPosts: List<Post> = emptyList(),
) : FeedRepository {
    val feedFlow = MutableStateFlow(initialPosts)

    var refreshCount = 0
    var refreshError: Throwable? = null
    var refreshGate: CompletableDeferred<Unit>? = null

    var setLikedError: Throwable? = null
    val setLikedCalls = mutableListOf<Pair<String, Boolean>>()

    override fun feed(): Flow<List<Post>> = feedFlow

    override suspend fun refresh() {
        refreshCount++
        refreshGate?.await()
        refreshError?.let { throw it }
    }

    override suspend fun setLiked(postId: String, liked: Boolean) {
        setLikedCalls.add(postId to liked)
        setLikedError?.let { throw it }
    }
}

class FeedViewModelTest {
    private val testDispatcher = StandardTestDispatcher()
    private val tempDirs = mutableListOf<File>()

    @BeforeTest
    fun setUp() {
        Dispatchers.setMain(testDispatcher)
    }

    @AfterTest
    fun tearDown() {
        Dispatchers.resetMain()
        tempDirs.forEach { it.deleteRecursively() }
    }

    private fun newCacheDir(): File {
        val dir = Files.createTempDirectory("feed-viewmodel-test").toFile()
        tempDirs.add(dir)
        return dir
    }

    private fun samplePost(id: String = "p1", likeCount: Int = 5, likedByMe: Boolean = false) =
        Post(id = id, authorName = "Ada", text = "hello", likeCount = likeCount, likedByMe = likedByMe)

    @Test
    fun `loads feed and refreshes on init`() = runTest(testDispatcher) {
        val repository = FakeFeedRepository(initialPosts = listOf(samplePost()))
        val viewModel = FeedViewModel(repository, newCacheDir(), testDispatcher)

        advanceUntilIdle()

        assertEquals(1, repository.refreshCount)
        assertEquals(listOf(samplePost()), viewModel.uiState.value.posts)
        assertFalse(viewModel.uiState.value.isRefreshing)
        assertNull(viewModel.uiState.value.error)
    }

    @Test
    fun `pull to refresh sets isRefreshing while in flight`() = runTest(testDispatcher) {
        val repository = FakeFeedRepository()
        val viewModel = FeedViewModel(repository, newCacheDir(), testDispatcher)
        advanceUntilIdle() // let the initial refresh from init finish

        val gate = CompletableDeferred<Unit>()
        repository.refreshGate = gate
        viewModel.refresh()
        runCurrent() // start the refresh coroutine up to the suspension point

        assertTrue(viewModel.uiState.value.isRefreshing)

        gate.complete(Unit)
        advanceUntilIdle()

        assertFalse(viewModel.uiState.value.isRefreshing)
        assertEquals(2, repository.refreshCount)
    }

    @Test
    fun `refresh failure surfaces an error message`() = runTest(testDispatcher) {
        val repository = FakeFeedRepository()
        repository.refreshError = RuntimeException("network down")
        val viewModel = FeedViewModel(repository, newCacheDir(), testDispatcher)

        advanceUntilIdle()

        assertEquals("network down", viewModel.uiState.value.error)
        assertFalse(viewModel.uiState.value.isRefreshing)
    }

    @Test
    fun `toggleLike updates optimistically before the repository call resolves`() = runTest(testDispatcher) {
        val repository = FakeFeedRepository(initialPosts = listOf(samplePost(likeCount = 5, likedByMe = false)))
        val viewModel = FeedViewModel(repository, newCacheDir(), testDispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p1")

        val post = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertTrue(post.likedByMe)
        assertEquals(6, post.likeCount)

        advanceUntilIdle()

        val settled = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertTrue(settled.likedByMe)
        assertEquals(6, settled.likeCount)
        assertEquals(listOf("p1" to true), repository.setLikedCalls)
        assertNull(viewModel.uiState.value.error)
    }

    @Test
    fun `toggleLike rolls back when the repository call fails`() = runTest(testDispatcher) {
        val repository = FakeFeedRepository(initialPosts = listOf(samplePost(likeCount = 5, likedByMe = false)))
        repository.setLikedError = RuntimeException("could not save like")
        val viewModel = FeedViewModel(repository, newCacheDir(), testDispatcher)
        advanceUntilIdle()

        viewModel.toggleLike("p1")

        val optimistic = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertTrue(optimistic.likedByMe)
        assertEquals(6, optimistic.likeCount)

        advanceUntilIdle()

        val rolledBack = viewModel.uiState.value.posts.single { it.id == "p1" }
        assertFalse(rolledBack.likedByMe)
        assertEquals(5, rolledBack.likeCount)
        assertEquals("could not save like", viewModel.uiState.value.error)
    }

    @Test
    fun `draft text is persisted to the cache dir and restored by a new view model`() = runTest(testDispatcher) {
        val cacheDir = newCacheDir()
        val repository = FakeFeedRepository()
        val viewModel = FeedViewModel(repository, cacheDir, testDispatcher)
        advanceUntilIdle()
        assertEquals("", viewModel.uiState.value.draftText)

        viewModel.updateDraft("hello world")
        assertEquals("hello world", viewModel.uiState.value.draftText)

        advanceUntilIdle()
        val draftFile = File(cacheDir, "feed_draft.json")
        assertTrue(draftFile.exists())
        assertTrue(draftFile.readText().contains("hello world"))

        val restored = FeedViewModel(FakeFeedRepository(), cacheDir, testDispatcher)
        advanceUntilIdle()

        assertEquals("hello world", restored.uiState.value.draftText)
    }

    @Test
    fun `missing draft file leaves draft text blank`() = runTest(testDispatcher) {
        val viewModel = FeedViewModel(FakeFeedRepository(), newCacheDir(), testDispatcher)
        advanceUntilIdle()

        assertEquals("", viewModel.uiState.value.draftText)
    }
}

