import com.acme.app.data.Account
import com.acme.app.data.AccountApi
import java.io.File
import kotlin.time.Duration
import kotlin.time.Duration.Companion.minutes
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.collect
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.decodeFromString
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

/** Progress of an in-flight [SyncManager.sync] run. */
data class SyncProgress(
    val accountsDone: Int,
    val totalAccounts: Int,
    val currentAccount: Account?,
)

@Serializable
private data class CursorFile(val cursors: Map<String, String> = emptyMap())

/**
 * Syncs every account's changes via [AccountApi], paging through `changesSince` until there's
 * no next cursor. Each account's last cursor is persisted to [cursorStoreFile] so the next
 * sync resumes instead of starting over.
 */
class SyncManager(
    private val accountApi: AccountApi,
    private val cursorStoreFile: File,
    private val statusStore: SyncStatusStore = SyncStatusStore(),
    private val ioDispatcher: CoroutineDispatcher = Dispatchers.IO,
) {
    private val json = Json { ignoreUnknownKeys = true }

    fun sync(): Flow<SyncProgress> = flow {
        val accounts = accountApi.accounts()
        var cursors = loadCursors()
        emit(SyncProgress(accountsDone = 0, totalAccounts = accounts.size, currentAccount = null))
        try {
            accounts.forEachIndexed { index, account ->
                emit(SyncProgress(index, accounts.size, account))
                cursors = syncAccount(account, cursors)
                emit(SyncProgress(index + 1, accounts.size, account))
            }
            statusStore.reportSuccess()
        } catch (t: Throwable) {
            statusStore.reportError(t)
            throw t
        }
    }

    private suspend fun syncAccount(account: Account, cursors: Map<String, String>): Map<String, String> {
        var current = cursors
        var cursor = current[account.id]
        while (true) {
            val page = accountApi.changesSince(account.id, cursor)
            val next = page.nextCursor ?: break
            cursor = next
            current = current + (account.id to next)
            saveCursors(current)
        }
        return current
    }

    private suspend fun loadCursors(): Map<String, String> = withContext(ioDispatcher) {
        if (!cursorStoreFile.exists()) return@withContext emptyMap()
        runCatching {
            json.decodeFromString<CursorFile>(cursorStoreFile.readText()).cursors
        }.getOrDefault(emptyMap())
    }

    private suspend fun saveCursors(cursors: Map<String, String>) = withContext(ioDispatcher) {
        cursorStoreFile.parentFile?.mkdirs()
        cursorStoreFile.writeText(json.encodeToString(CursorFile(cursors)))
    }

    /** Runs [sync] immediately, then every [interval], until [scope] is cancelled. */
    fun startPeriodicSync(scope: CoroutineScope, interval: Duration = 15.minutes): Job =
        scope.launch {
            while (isActive) {
                sync().collect()
                delay(interval)
            }
        }
}

package com.acme.app.sync

import java.time.Instant
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

data class SyncStatus(
    val lastSyncTime: Instant? = null,
    val lastError: Throwable? = null,
)

/** Holds the outcome of the most recent [SyncManager] run for the UI to observe. */
class SyncStatusStore {
    private val _status = MutableStateFlow(SyncStatus())
    val status: StateFlow<SyncStatus> = _status.asStateFlow()

    fun reportSuccess(time: Instant = Instant.now()) {
        _status.value = SyncStatus(lastSyncTime = time, lastError = null)
    }

    fun reportError(error: Throwable) {
        _status.value = _status.value.copy(lastError = error)
    }
}

