private class FakeAccountApi(
    private val accounts: List<Account>,
    private val pagesByAccount: Map<String, List<ChangePage>>,
) : AccountApi {
    val callsByAccount = mutableMapOf<String, MutableList<String?>>()
    var failNextCallFor: String? = null

    override suspend fun accounts(): List<Account> = accounts

    override suspend fun changesSince(accountId: String, cursor: String?): ChangePage {
        if (failNextCallFor == accountId) {
            failNextCallFor = null
            throw RuntimeException("boom")
        }
        val calls = callsByAccount.getOrPut(accountId) { mutableListOf() }
        calls.add(cursor)
        return pagesByAccount.getValue(accountId)[calls.size - 1]
    }
}

class SyncManagerTest {

    private fun cursorFile(): File = File.createTempFile("cursors", ".json").apply { deleteOnExit() }

    private fun testDispatcher(scope: kotlinx.coroutines.test.TestScope) =
        kotlinx.coroutines.test.UnconfinedTestDispatcher(scope.testScheduler)

    @Test
    fun `pages through changesSince until nextCursor is null`() = runTest {
        val account = Account("a1", "Ada")
        val api = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf(
                "a1" to listOf(
                    ChangePage(items = listOf("x1"), nextCursor = "c1"),
                    ChangePage(items = listOf("x2"), nextCursor = "c2"),
                    ChangePage(items = listOf("x3"), nextCursor = null),
                ),
            ),
        )
        val manager = SyncManager(api, cursorFile(), ioDispatcher = testDispatcher(this))

        manager.sync().toList()

        assertEquals(listOf(null, "c1", "c2"), api.callsByAccount.getValue("a1"))
    }

    @Test
    fun `persists last cursor so the next sync resumes`() = runTest {
        val account = Account("a1", "Ada")
        val file = cursorFile()
        val dispatcher = testDispatcher(this)
        val firstRunApi = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf(
                "a1" to listOf(
                    ChangePage(items = listOf("x1"), nextCursor = "c1"),
                    ChangePage(items = listOf("x2"), nextCursor = null),
                ),
            ),
        )
        SyncManager(firstRunApi, file, ioDispatcher = dispatcher).sync().toList()
        assertEquals(listOf(null, "c1"), firstRunApi.callsByAccount.getValue("a1"))

        val secondRunApi = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf(
                "a1" to listOf(ChangePage(items = emptyList(), nextCursor = null)),
            ),
        )
        SyncManager(secondRunApi, file, ioDispatcher = dispatcher).sync().toList()

        assertEquals(listOf("c1"), secondRunApi.callsByAccount.getValue("a1"))
    }

    @Test
    fun `reports progress for accounts done and total, and current account`() = runTest {
        val a1 = Account("a1", "Ada")
        val a2 = Account("a2", "Bob")
        val api = FakeAccountApi(
            accounts = listOf(a1, a2),
            pagesByAccount = mapOf(
                "a1" to listOf(ChangePage(emptyList(), null)),
                "a2" to listOf(ChangePage(emptyList(), null)),
            ),
        )
        val manager = SyncManager(api, cursorFile(), ioDispatcher = testDispatcher(this))

        val progress = manager.sync().toList()

        assertEquals(
            listOf(
                SyncProgress(0, 2, null),
                SyncProgress(0, 2, a1),
                SyncProgress(1, 2, a1),
                SyncProgress(1, 2, a2),
                SyncProgress(2, 2, a2),
            ),
            progress,
        )
    }

    @Test
    fun `records success in the status store after a sync`() = runTest {
        val account = Account("a1", "Ada")
        val api = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf("a1" to listOf(ChangePage(emptyList(), null))),
        )
        val statusStore = SyncStatusStore()
        val manager = SyncManager(api, cursorFile(), statusStore, testDispatcher(this))

        manager.sync().toList()

        val status = statusStore.status.value
        assertNull(status.lastError)
        assertTrue(status.lastSyncTime != null)
    }

    @Test
    fun `records an error in the status store and rethrows`() = runTest {
        val account = Account("a1", "Ada")
        val api = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf("a1" to listOf(ChangePage(emptyList(), null))),
        )
        api.failNextCallFor = "a1"
        val statusStore = SyncStatusStore()
        val manager = SyncManager(api, cursorFile(), statusStore, testDispatcher(this))

        assertFailsWith<RuntimeException> { manager.sync().toList() }

        assertEquals("boom", statusStore.status.value.lastError?.message)
        assertNull(statusStore.status.value.lastSyncTime)
    }

    @Test
    fun `starts a periodic sync every 15 minutes`() = runTest {
        val account = Account("a1", "Ada")
        val api = FakeAccountApi(
            accounts = listOf(account),
            pagesByAccount = mapOf(
                "a1" to List(10) { ChangePage(emptyList(), null) },
            ),
        )
        val manager = SyncManager(api, cursorFile(), ioDispatcher = testDispatcher(this))

        val job = manager.startPeriodicSync(backgroundScope)
        runCurrent()
        assertEquals(1, api.callsByAccount.getValue("a1").size)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(2, api.callsByAccount.getValue("a1").size)

        advanceTimeBy(15.minutes)
        runCurrent()
        assertEquals(3, api.callsByAccount.getValue("a1").size)

        job.cancel()
    }
}

//! A small line-based TCP chat server.
//!
//! Clients connect, send a nickname as their first line, and every line
//! sent afterwards is broadcast to all other connected clients as
//! `nick: text`. Sending `/who` replies (to the sender only) with the
//! number of currently connected users. Clients idle for longer than the
//! configured idle timeout are disconnected.

use std::io;
use std::net::SocketAddr;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use tokio::fs::OpenOptions;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream, ToSocketAddrs};
use tokio::sync::{broadcast, Mutex};
use tokio::time::Instant;

/// Default idle timeout: clients that send nothing for this long are disconnected.
pub const DEFAULT_IDLE_TIMEOUT: Duration = Duration::from_secs(5 * 60);

const BROADCAST_CAPACITY: usize = 256;

/// A running (not yet started) chat server bound to a TCP address.
pub struct ChatServer {
    listener: TcpListener,
    tx: broadcast::Sender<(u64, String)>,
    user_count: Arc<AtomicUsize>,
    next_id: Arc<AtomicU64>,
    log_path: PathBuf,
    idle_timeout: Duration,
}

impl ChatServer {
    /// Bind the server to `addr`, logging every broadcast chat message to `log_path`.
    pub async fn bind(addr: impl ToSocketAddrs, log_path: impl AsRef<Path>) -> io::Result<Self> {
        let listener = TcpListener::bind(addr).await?;
        let (tx, _rx) = broadcast::channel(BROADCAST_CAPACITY);
        Ok(Self {
            listener,
            tx,
            user_count: Arc::new(AtomicUsize::new(0)),
            next_id: Arc::new(AtomicU64::new(0)),
            log_path: log_path.as_ref().to_path_buf(),
            idle_timeout: DEFAULT_IDLE_TIMEOUT,
        })
    }

    /// Override the idle timeout (defaults to 5 minutes).
    pub fn idle_timeout(mut self, timeout: Duration) -> Self {
        self.idle_timeout = timeout;
        self
    }

    /// The local address the server is bound to.
    pub fn local_addr(&self) -> io::Result<SocketAddr> {
        self.listener.local_addr()
    }

    /// Run the server until Ctrl-C is received.
    pub async fn run(self) -> io::Result<()> {
        self.run_until(async {
            let _ = tokio::signal::ctrl_c().await;
        })
        .await
    }

    /// Run the server, accepting connections until `shutdown` resolves.
    pub async fn run_until(self, shutdown: impl std::future::Future<Output = ()>) -> io::Result<()> {
        let log = Arc::new(Mutex::new(
            OpenOptions::new()
                .create(true)
                .append(true)
                .open(&self.log_path)
                .await?,
        ));

        tokio::pin!(shutdown);
        loop {
            tokio::select! {
                _ = &mut shutdown => break,
                accepted = self.listener.accept() => {
                    let (socket, _addr) = match accepted {
                        Ok(v) => v,
                        Err(_) => continue,
                    };
                    let tx = self.tx.clone();
                    let count = self.user_count.clone();
                    let log = log.clone();
                    let idle_timeout = self.idle_timeout;
                    let id = self.next_id.fetch_add(1, Ordering::SeqCst);
                    tokio::spawn(async move {
                        let _ = handle_connection(socket, tx, count, log, idle_timeout, id).await;
                    });
                }
            }
        }
        Ok(())
    }
}

struct CountGuard(Arc<AtomicUsize>);

impl Drop for CountGuard {
    fn drop(&mut self) {
        self.0.fetch_sub(1, Ordering::SeqCst);
    }
}

async fn handle_connection(
    socket: TcpStream,
    tx: broadcast::Sender<(u64, String)>,
    count: Arc<AtomicUsize>,
    log: Arc<Mutex<tokio::fs::File>>,
    idle_timeout: Duration,
    id: u64,
) -> io::Result<()> {
    let (reader, mut writer) = socket.into_split();
    let mut reader = BufReader::new(reader);
    let mut rx = tx.subscribe();

    let mut nick_line = String::new();
    let n = match tokio::time::timeout(idle_timeout, reader.read_line(&mut nick_line)).await {
        Ok(result) => result?,
        Err(_) => return Ok(()), // idle before sending a nickname
    };
    if n == 0 {
        return Ok(());
    }
    let nick = nick_line.trim().to_string();
    if nick.is_empty() {
        return Ok(());
    }

    count.fetch_add(1, Ordering::SeqCst);
    let _guard = CountGuard(count.clone());

    let mut line = String::new();
    let mut deadline = Instant::now() + idle_timeout;
    loop {
        line.clear();
        tokio::select! {
            result = reader.read_line(&mut line) => {
                let n = result?;
                if n == 0 {
                    break;
                }
                deadline = Instant::now() + idle_timeout;
                let text = line.trim_end();
                if text.is_empty() {
                    continue;
                }
                if text == "/who" {
                    let reply = format!("* {} user(s) connected\n", count.load(Ordering::SeqCst));
                    writer.write_all(reply.as_bytes()).await?;
                    continue;
                }
                let formatted = format!("{}: {}", nick, text);
                {
                    let mut file = log.lock().await;
                    file.write_all(formatted.as_bytes()).await?;
                    file.write_all(b"\n").await?;
                    file.flush().await?;
                }
                let _ = tx.send((id, formatted));
            }
            recv = rx.recv() => {
                match recv {
                    Ok((sender_id, msg)) => {
                        if sender_id != id {
                            writer.write_all(msg.as_bytes()).await?;
                            writer.write_all(b"\n").await?;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => {}
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
            _ = tokio::time::sleep_until(deadline) => {
                break;
            }
        }
    }
    Ok(())
}

