pub mod config;

use relay::chat::ChatServer;
use relay::config::Config;

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let config = Config::from_env();
    println!("relay starting on {}", config.listen_addr);

    let chat_addr = std::env::var("CHAT_LISTEN").unwrap_or_else(|_| "127.0.0.1:7001".into());
    let server = ChatServer::bind(&chat_addr, "chat.log").await?;
    println!("chat server listening on {}", server.local_addr()?);
    server.run().await
}

use std::net::SocketAddr;
use std::path::PathBuf;
use std::time::Duration;

use relay::chat::ChatServer;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
use tokio::net::tcp::{OwnedReadHalf, OwnedWriteHalf};
use tokio::net::TcpStream;

fn temp_log_path(name: &str) -> PathBuf {
    std::env::temp_dir().join(format!(
        "relay_chat_test_{}_{}_{}.log",
        std::process::id(),
        name,
        rand_suffix()
    ))
}

fn rand_suffix() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

async fn connect_and_login(addr: SocketAddr, nick: &str) -> (BufReader<OwnedReadHalf>, OwnedWriteHalf) {
    let stream = TcpStream::connect(addr).await.unwrap();
    let (r, mut w) = stream.into_split();
    let r = BufReader::new(r);
    w.write_all(format!("{}\n", nick).as_bytes()).await.unwrap();
    (r, w)
}

#[tokio::test]
async fn broadcasts_messages_to_other_clients_only() {
    let log_path = temp_log_path("broadcast");
    let server = ChatServer::bind("127.0.0.1:0", &log_path).await.unwrap();
    let addr = server.local_addr().unwrap();
    let handle = tokio::spawn(server.run_until(async {
        tokio::time::sleep(Duration::from_secs(10)).await;
    }));

    let (mut r1, mut w1) = connect_and_login(addr, "alice").await;
    let (mut r2, _w2) = connect_and_login(addr, "bob").await;

    tokio::time::sleep(Duration::from_millis(100)).await;

    w1.write_all(b"hello there\n").await.unwrap();

    let mut line = String::new();
    tokio::time::timeout(Duration::from_secs(2), r2.read_line(&mut line))
        .await
        .expect("bob should receive alice's message")
        .unwrap();
    assert_eq!(line.trim_end(), "alice: hello there");

    let mut own = String::new();
    let result = tokio::time::timeout(Duration::from_millis(200), r1.read_line(&mut own)).await;
    assert!(result.is_err(), "sender should not receive their own broadcast message");

    handle.abort();
    let _ = tokio::fs::remove_file(&log_path).await;
}

#[tokio::test]
async fn who_reports_connected_user_count() {
    let log_path = temp_log_path("who");
    let server = ChatServer::bind("127.0.0.1:0", &log_path).await.unwrap();
    let addr = server.local_addr().unwrap();
    let handle = tokio::spawn(server.run_until(async {
        tokio::time::sleep(Duration::from_secs(10)).await;
    }));

    let (mut r1, mut w1) = connect_and_login(addr, "alice").await;
    let (_r2, _w2) = connect_and_login(addr, "bob").await;

    tokio::time::sleep(Duration::from_millis(100)).await;

    w1.write_all(b"/who\n").await.unwrap();
    let mut line = String::new();
    tokio::time::timeout(Duration::from_secs(2), r1.read_line(&mut line))
        .await
        .expect("expected a /who reply")
        .unwrap();
    assert!(line.contains('2'), "expected /who reply to mention 2 users, got: {line:?}");

    handle.abort();
    let _ = tokio::fs::remove_file(&log_path).await;
}

#[tokio::test]
async fn disconnects_idle_clients() {
    let log_path = temp_log_path("idle");
    let server = ChatServer::bind("127.0.0.1:0", &log_path)
        .await
        .unwrap()
        .idle_timeout(Duration::from_millis(200));
    let addr = server.local_addr().unwrap();
    let handle = tokio::spawn(server.run_until(async {
        tokio::time::sleep(Duration::from_secs(10)).await;
    }));

    let (mut r1, _w1) = connect_and_login(addr, "alice").await;

    let mut buf = [0u8; 16];
    let n = tokio::time::timeout(Duration::from_secs(2), r1.read(&mut buf))
        .await
        .expect("connection should close after idle timeout")
        .unwrap();
    assert_eq!(n, 0, "expected EOF after idle timeout");

    handle.abort();
    let _ = tokio::fs::remove_file(&log_path).await;
}

#[tokio::test]
async fn logs_messages_to_file() {
    let log_path = temp_log_path("log");
    let server = ChatServer::bind("127.0.0.1:0", &log_path).await.unwrap();
    let addr = server.local_addr().unwrap();
    let handle = tokio::spawn(server.run_until(async {
        tokio::time::sleep(Duration::from_secs(10)).await;
    }));

    let (_r1, mut w1) = connect_and_login(addr, "alice").await;
    tokio::time::sleep(Duration::from_millis(100)).await;
    w1.write_all(b"logged message\n").await.unwrap();
    tokio::time::sleep(Duration::from_millis(200)).await;

    let contents = tokio::fs::read_to_string(&log_path).await.unwrap();
    assert!(contents.contains("alice: logged message"));

    handle.abort();
    let _ = tokio::fs::remove_file(&log_path).await;
}

#[tokio::test]
async fn run_until_stops_when_shutdown_resolves() {
    let log_path = temp_log_path("shutdown");
    let server = ChatServer::bind("127.0.0.1:0", &log_path).await.unwrap();

    let result = tokio::time::timeout(
        Duration::from_secs(2),
        server.run_until(async { tokio::time::sleep(Duration::from_millis(50)).await }),
    )
    .await;

    assert!(result.is_ok(), "run_until should return once the shutdown future resolves");
    let _ = tokio::fs::remove_file(&log_path).await;
}

