//! User profile loading, caching, and the SQL helper used by the reporting job.

use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};

use thiserror::Error;
use tokio::sync::Mutex;
use tokio::time::{Duration, Instant};

/// A user profile as returned by a [`ProfileBackend`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Profile {
    pub id: String,
    pub name: String,
    pub team: String,
    pub email: String,
}

/// Error returned by a [`ProfileBackend`] when a profile can't be fetched.
#[derive(Debug, Clone, PartialEq, Eq, Error)]
pub enum BackendError {
    #[error("profile not found: {0}")]
    NotFound(String),
    #[error("backend unavailable: {0}")]
    Unavailable(String),
}

/// Source of truth that [`ProfileService`] fetches profiles from on a cache miss.
pub trait ProfileBackend {
    /// Fetch a single profile by id.
    fn fetch(
        &self,
        id: &str,
    ) -> impl std::future::Future<Output = Result<Profile, BackendError>> + Send;
}

impl<T: ProfileBackend + Send + Sync + ?Sized> ProfileBackend for std::sync::Arc<T> {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError> {
        (**self).fetch(id).await
    }
}

struct CacheEntry {
    profile: Profile,
    inserted_at: Instant,
}

/// Loads profiles through a [`ProfileBackend`], caching results in memory for `ttl`.
pub struct ProfileService<B: ProfileBackend> {
    backend: B,
    ttl: Duration,
    cache: Mutex<HashMap<String, CacheEntry>>,
}

impl<B: ProfileBackend> ProfileService<B> {
    pub fn new(backend: B, ttl: Duration) -> Self {
        Self {
            backend,
            ttl,
            cache: Mutex::new(HashMap::new()),
        }
    }

    /// Load a single profile, serving it from the cache if a fresh entry exists.
    pub async fn load(&self, id: &str) -> Result<Profile, BackendError> {
        {
            let cache = self.cache.lock().await;
            if let Some(entry) = cache.get(id) {
                if entry.inserted_at.elapsed() < self.ttl {
                    return Ok(entry.profile.clone());
                }
            }
        }

        let profile = self.backend.fetch(id).await?;

        let mut cache = self.cache.lock().await;
        cache.insert(
            id.to_string(),
            CacheEntry {
                profile: profile.clone(),
                inserted_at: Instant::now(),
            },
        );
        Ok(profile)
    }

    /// Load multiple profiles for the team page, preserving the input order.
    /// Each id resolves independently, so one missing profile doesn't fail the rest.
    pub async fn load_many(&self, ids: &[String]) -> Vec<Result<Profile, BackendError>> {
        let mut results = Vec::with_capacity(ids.len());
        for id in ids {
            results.push(self.load(id).await);
        }
        results
    }
}

/// OAuth-style credentials for an external API.
#[derive(Clone)]
pub struct ApiCredentials {
    pub client_id: String,
    pub client_secret: String,
    pub access_token: String,
    /// Unix timestamp (seconds) at which `access_token` expires.
    pub expires_at: i64,
}

impl ApiCredentials {
    /// Seconds remaining before `access_token` expires, relative to now.
    /// Negative once the token has already expired.
    pub fn seconds_until_expiry(&self) -> i64 {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock is before the Unix epoch")
            .as_secs() as i64;
        self.expires_at - now
    }
}

// `client_secret` and `access_token` must never end up in logs via a stray `{:?}`.
impl std::fmt::Debug for ApiCredentials {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ApiCredentials")
            .field("client_id", &self.client_id)
            .field("client_secret", &"[redacted]")
            .field("access_token", &"[redacted]")
            .field("expires_at", &self.expires_at)
            .finish()
    }
}

/// A parameterized SQLite query, ready to run through a driver that binds
/// `params` positionally (e.g. rusqlite's `?1`, `?2`, ...). Values are never
/// interpolated into `sql` directly, so callers can't accidentally build an
/// injectable query out of user-supplied `name_prefix` / `team` input.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SqlQuery {
    pub sql: String,
    pub params: Vec<String>,
}

/// Builds the SELECT the reporting job runs to find profiles on a given team
/// whose name starts with `name_prefix`.
pub fn profile_search_sql(name_prefix: &str, team: &str) -> SqlQuery {
    SqlQuery {
        sql: "SELECT id, name, team, email FROM profiles \
              WHERE name LIKE ?1 AND team = ?2 \
              ORDER BY name"
            .to_string(),
        params: vec![format!("{name_prefix}%"), team.to_string()],
    }
}

use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use relay::profiles::{
    profile_search_sql, ApiCredentials, BackendError, Profile, ProfileBackend, ProfileService,
};
use tokio::time::Duration;

struct FakeBackend {
    profiles: HashMap<String, Profile>,
    calls: AtomicUsize,
}

impl FakeBackend {
    fn new(profiles: Vec<Profile>) -> Self {
        Self {
            profiles: profiles.into_iter().map(|p| (p.id.clone(), p)).collect(),
            calls: AtomicUsize::new(0),
        }
    }

    fn call_count(&self) -> usize {
        self.calls.load(Ordering::SeqCst)
    }
}

impl ProfileBackend for FakeBackend {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.profiles
            .get(id)
            .cloned()
            .ok_or_else(|| BackendError::NotFound(id.to_string()))
    }
}

fn alice() -> Profile {
    Profile {
        id: "u1".into(),
        name: "Alice".into(),
        team: "platform".into(),
        email: "alice@example.com".into(),
    }
}

fn bob() -> Profile {
    Profile {
        id: "u2".into(),
        name: "Bob".into(),
        team: "platform".into(),
        email: "bob@example.com".into(),
    }
}

#[tokio::test]
async fn load_returns_the_profile() {
    let backend = FakeBackend::new(vec![alice()]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let profile = service.load("u1").await.unwrap();
    assert_eq!(profile, alice());
}

#[tokio::test]
async fn load_propagates_backend_errors() {
    let backend = FakeBackend::new(vec![]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let err = service.load("missing").await.unwrap_err();
    assert_eq!(err, BackendError::NotFound("missing".to_string()));
}

#[tokio::test]
async fn load_serves_repeated_calls_from_the_cache() {
    let backend = Arc::new(FakeBackend::new(vec![alice()]));
    let service = ProfileService::new(backend.clone(), Duration::from_secs(60));

    service.load("u1").await.unwrap();
    service.load("u1").await.unwrap();
    service.load("u1").await.unwrap();

    assert_eq!(backend.call_count(), 1);
}

#[tokio::test(start_paused = true)]
async fn load_refetches_once_the_ttl_expires() {
    let backend = Arc::new(FakeBackend::new(vec![alice()]));
    let service = ProfileService::new(backend.clone(), Duration::from_secs(30));

    service.load("u1").await.unwrap();
    assert_eq!(backend.call_count(), 1);

    tokio::time::advance(Duration::from_secs(10)).await;
    service.load("u1").await.unwrap();
    assert_eq!(backend.call_count(), 1, "still within the ttl");

    tokio::time::advance(Duration::from_secs(25)).await;
    service.load("u1").await.unwrap();
    assert_eq!(backend.call_count(), 2, "ttl elapsed, should refetch");
}

#[tokio::test]
async fn load_many_resolves_each_id_independently() {
    let backend = FakeBackend::new(vec![alice(), bob()]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let ids = vec!["u1".to_string(), "missing".to_string(), "u2".to_string()];
    let results = service.load_many(&ids).await;

    assert_eq!(results.len(), 3);
    assert_eq!(results[0].as_ref().unwrap(), &alice());
    assert_eq!(
        results[1].as_ref().unwrap_err(),
        &BackendError::NotFound("missing".to_string())
    );
    assert_eq!(results[2].as_ref().unwrap(), &bob());
}

#[test]
fn seconds_until_expiry_is_positive_for_a_future_token() {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;

    let creds = ApiCredentials {
        client_id: "id".into(),
        client_secret: "secret".into(),
        access_token: "token".into(),
        expires_at: now + 120,
    };

    let remaining = creds.seconds_until_expiry();
    assert!((110..=120).contains(&remaining), "remaining was {remaining}");
}

#[test]
fn seconds_until_expiry_is_negative_for_an_expired_token() {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;

    let creds = ApiCredentials {
        client_id: "id".into(),
        client_secret: "secret".into(),
        access_token: "token".into(),
        expires_at: now - 30,
    };

    assert!(creds.seconds_until_expiry() <= -30);
}

#[test]
fn api_credentials_debug_redacts_secrets() {
    let creds = ApiCredentials {
        client_id: "id".into(),
        client_secret: "super-secret".into(),
        access_token: "top-secret-token".into(),
        expires_at: 0,
    };

    let debug = format!("{creds:?}");
    assert!(!debug.contains("super-secret"));
    assert!(!debug.contains("top-secret-token"));
    assert!(debug.contains("id"));
}

#[test]
fn profile_search_sql_uses_placeholders_instead_of_interpolating_input() {
    let query = profile_search_sql("Ali'; DROP TABLE profiles; --", "platform");

    assert!(query.sql.contains("?1"));
    assert!(query.sql.contains("?2"));
    assert!(!query.sql.contains("DROP TABLE"));
    assert_eq!(
        query.params,
        vec!["Ali'; DROP TABLE profiles; --%".to_string(), "platform".to_string()]
    );
}

#[test]
fn profile_search_sql_appends_a_prefix_wildcard() {
    let query = profile_search_sql("Al", "platform");
    assert_eq!(query.params[0], "Al%");
    assert_eq!(query.params[1], "platform");
}

//! A small line-based TCP chat server.
//!
//! Clients connect, send a nickname as their first line, then every
//! subsequent line they send is broadcast to all other connected clients as
//! `nick: text`. Sending `/who` prints the number of connected users back to
//! the sender instead of broadcasting. Clients idle for longer than the
//! configured idle timeout are disconnected. Every chat message is appended
//! to the server's log file.

use std::net::SocketAddr;
use std::path::Path;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use tokio::fs::{File, OpenOptions};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::broadcast;
use tokio::sync::broadcast::error::RecvError;
use tokio::sync::Mutex;
use tokio::time::timeout;

/// Default idle timeout: clients that send nothing for this long are disconnected.
pub const DEFAULT_IDLE_TIMEOUT: Duration = Duration::from_secs(5 * 60);

/// Sender id used for server-generated messages (join/leave notices), which
/// never matches a real client id and so is delivered to every client.
const SYSTEM_SENDER: usize = usize::MAX;

#[derive(Clone)]
struct ChatMessage {
    sender: usize,
    text: String,
}

struct SharedState {
    tx: broadcast::Sender<ChatMessage>,
    user_count: AtomicUsize,
    next_id: AtomicUsize,
    idle_timeout: Duration,
    log: Mutex<File>,
}

impl SharedState {
    async fn log_line(&self, line: &str) {
        let mut log = self.log.lock().await;
        let _ = log.write_all(line.as_bytes()).await;
        let _ = log.write_all(b"\n").await;
        let _ = log.flush().await;
    }
}

/// A running (but not yet accepting) line-based TCP chat server.
pub struct ChatServer {
    listener: TcpListener,
    state: Arc<SharedState>,
}

impl ChatServer {
    /// Bind a chat server to `addr`, logging chat activity to `log_path`,
    /// using the default idle timeout of 5 minutes.
    pub async fn bind(addr: &str, log_path: impl AsRef<Path>) -> std::io::Result<Self> {
        Self::bind_with_idle_timeout(addr, log_path, DEFAULT_IDLE_TIMEOUT).await
    }

    /// Like [`ChatServer::bind`], but with a configurable idle timeout
    /// (mainly useful for tests).
    pub async fn bind_with_idle_timeout(
        addr: &str,
        log_path: impl AsRef<Path>,
        idle_timeout: Duration,
    ) -> std::io::Result<Self> {
        let listener = TcpListener::bind(addr).await?;
        let log = OpenOptions::new()
            .create(true)
            .append(true)
            .open(log_path)
            .await?;
        let (tx, _rx) = broadcast::channel(1024);
        let state = Arc::new(SharedState {
            tx,
            user_count: AtomicUsize::new(0),
            next_id: AtomicUsize::new(0),
            idle_timeout,
            log: Mutex::new(log),
        });
        Ok(Self { listener, state })
    }

    /// The address the server is actually listening on.
    pub fn local_addr(&self) -> std::io::Result<SocketAddr> {
        self.listener.local_addr()
    }

    /// The number of currently connected clients.
    pub fn user_count(&self) -> usize {
        self.state.user_count.load(Ordering::SeqCst)
    }

    /// Accept connections, handling each on its own task, until `shutdown`
    /// resolves.
    pub async fn run(self, shutdown: impl std::future::Future<Output = ()>) -> std::io::Result<()> {
        tokio::pin!(shutdown);
        loop {
            tokio::select! {
                _ = &mut shutdown => return Ok(()),
                accepted = self.listener.accept() => {
                    let (socket, _addr) = accepted?;
                    let state = self.state.clone();
                    tokio::spawn(handle_client(socket, state));
                }
            }
        }
    }
}

async fn handle_client(socket: TcpStream, state: Arc<SharedState>) {
    let (read_half, mut write_half) = socket.into_split();
    let mut reader = BufReader::new(read_half).lines();

    let nick = match timeout(state.idle_timeout, reader.next_line()).await {
        Ok(Ok(Some(line))) if !line.trim().is_empty() => line.trim().to_string(),
        _ => return,
    };

    let id = state.next_id.fetch_add(1, Ordering::SeqCst);
    state.user_count.fetch_add(1, Ordering::SeqCst);
    let mut rx = state.tx.subscribe();

    let joined = format!("{nick} has joined");
    state.log_line(&joined).await;
    let _ = state.tx.send(ChatMessage {
        sender: SYSTEM_SENDER,
        text: joined,
    });

    loop {
        tokio::select! {
            line = timeout(state.idle_timeout, reader.next_line()) => {
                match line {
                    Ok(Ok(Some(text))) => {
                        let text = text.trim_end();
                        if text == "/who" {
                            let count = state.user_count.load(Ordering::SeqCst);
                            let reply = format!("{count} user(s) connected\n");
                            if write_half.write_all(reply.as_bytes()).await.is_err() {
                                break;
                            }
                            continue;
                        }
                        let formatted = format!("{nick}: {text}");
                        state.log_line(&formatted).await;
                        let _ = state.tx.send(ChatMessage { sender: id, text: formatted });
                    }
                    Ok(Ok(None)) | Ok(Err(_)) => break,
                    Err(_elapsed) => {
                        let _ = write_half.write_all(b"idle timeout, disconnecting\n").await;
                        break;
                    }
                }
            }
            msg = rx.recv() => {
                match msg {
                    Ok(msg) if msg.sender != id => {
                        let line = format!("{}\n", msg.text);
                        if write_half.write_all(line.as_bytes()).await.is_err() {
                            break;
                        }
                    }
                    Ok(_) => {}
                    Err(RecvError::Lagged(_)) => {}
                    Err(RecvError::Closed) => break,
                }
            }
        }
    }

    state.user_count.fetch_sub(1, Ordering::SeqCst);
    let left = format!("{nick} has left");
    state.log_line(&left).await;
    let _ = state.tx.send(ChatMessage {
        sender: SYSTEM_SENDER,
        text: left,
    });
}

//! relay: a small Tokio service. Add modules below.

pub mod chat;
pub mod config;

use relay::chat::ChatServer;
use relay::config::Config;

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let config = Config::from_env();
    println!("relay starting on {}", config.listen_addr);

    let chat_addr = std::env::var("RELAY_CHAT_LISTEN").unwrap_or_else(|_| "127.0.0.1:7001".into());
    let server = ChatServer::bind(&chat_addr, "chat.log").await?;
    println!("chat server listening on {}", server.local_addr()?);

    let shutdown = async {
        let _ = tokio::signal::ctrl_c().await;
        println!("shutting down");
    };
    server.run(shutdown).await
}

use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use relay::chat::ChatServer;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::TcpStream;
use tokio::time::timeout;

const READ_TIMEOUT: Duration = Duration::from_secs(2);
const SETTLE: Duration = Duration::from_millis(50);

fn unique_log_path(tag: &str) -> std::path::PathBuf {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::SeqCst);
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    std::env::temp_dir().join(format!("relay-chat-test-{tag}-{nanos}-{n}.log"))
}

async fn read_line(reader: &mut (impl AsyncBufReadExt + Unpin)) -> String {
    let mut line = String::new();
    timeout(READ_TIMEOUT, reader.read_line(&mut line))
        .await
        .expect("timed out waiting for a line")
        .expect("read failed");
    line
}

/// Read lines, discarding any that don't match `expected`, until `expected`
/// shows up. Used because join/leave notices (and other clients' traffic)
/// may be interleaved with the line under test.
async fn read_until(reader: &mut (impl AsyncBufReadExt + Unpin), expected: &str) {
    loop {
        if read_line(reader).await == expected {
            return;
        }
    }
}

async fn connect_and_join(addr: std::net::SocketAddr, nick: &str) -> TcpStream {
    let mut stream = TcpStream::connect(addr).await.expect("connect failed");
    stream
        .write_all(format!("{nick}\n").as_bytes())
        .await
        .expect("write failed");
    // Give the server a moment to register the nick before the caller
    // relies on this client being counted / subscribed.
    tokio::time::sleep(SETTLE).await;
    stream
}

#[tokio::test]
async fn broadcasts_messages_with_sender_nick() {
    let log_path = unique_log_path("broadcast");
    let server = ChatServer::bind("127.0.0.1:0", &log_path)
        .await
        .expect("bind failed");
    let addr = server.local_addr().expect("no local addr");
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let server_task = tokio::spawn(server.run(async {
        let _ = shutdown_rx.await;
    }));

    let mut alice = connect_and_join(addr, "alice").await;
    let bob = connect_and_join(addr, "bob").await;
    let mut bob_reader = BufReader::new(bob);

    alice
        .write_all(b"hello there\n")
        .await
        .expect("write failed");

    read_until(&mut bob_reader, "alice: hello there\n").await;

    let _ = shutdown_tx.send(());
    server_task.await.expect("server task panicked").unwrap();
}

#[tokio::test]
async fn who_reports_connected_user_count() {
    let log_path = unique_log_path("who");
    let server = ChatServer::bind("127.0.0.1:0", &log_path)
        .await
        .expect("bind failed");
    let addr = server.local_addr().expect("no local addr");
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let server_task = tokio::spawn(server.run(async {
        let _ = shutdown_rx.await;
    }));

    let alice = connect_and_join(addr, "alice").await;
    let _bob = connect_and_join(addr, "bob").await;
    let _carol = connect_and_join(addr, "carol").await;

    let mut alice_reader = BufReader::new(alice);
    alice_reader
        .get_mut()
        .write_all(b"/who\n")
        .await
        .expect("write failed");
    read_until(&mut alice_reader, "3 user(s) connected\n").await;

    let _ = shutdown_tx.send(());
    server_task.await.expect("server task panicked").unwrap();
}

#[tokio::test]
async fn disconnects_idle_clients() {
    let log_path = unique_log_path("idle");
    let server = ChatServer::bind_with_idle_timeout(
        "127.0.0.1:0",
        &log_path,
        Duration::from_millis(200),
    )
    .await
    .expect("bind failed");
    let addr = server.local_addr().expect("no local addr");
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let server_task = tokio::spawn(server.run(async {
        let _ = shutdown_rx.await;
    }));

    let stream = connect_and_join(addr, "idle-nick").await;
    let mut reader = BufReader::new(stream);

    // Send nothing further; the idle timeout should kick in and the notice
    // (possibly preceded by this client's own join notice) should arrive.
    read_until(&mut reader, "idle timeout, disconnecting\n").await;

    let mut trailing = String::new();
    timeout(READ_TIMEOUT, reader.read_line(&mut trailing))
        .await
        .expect("timed out waiting for eof")
        .expect("read failed");
    assert_eq!(trailing, "", "connection should be closed after idle timeout");

    let _ = shutdown_tx.send(());
    server_task.await.expect("server task panicked").unwrap();
}

#[tokio::test]
async fn logs_messages_to_file() {
    let log_path = unique_log_path("log");
    let server = ChatServer::bind("127.0.0.1:0", &log_path)
        .await
        .expect("bind failed");
    let addr = server.local_addr().expect("no local addr");
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let server_task = tokio::spawn(server.run(async {
        let _ = shutdown_rx.await;
    }));

    let mut alice = connect_and_join(addr, "alice").await;
    alice
        .write_all(b"logged message\n")
        .await
        .expect("write failed");

    // Give the server a moment to process and flush the log write.
    tokio::time::sleep(SETTLE).await;

    let contents = tokio::fs::read_to_string(&log_path)
        .await
        .expect("failed to read log file");
    assert!(contents.contains("alice has joined"));
    assert!(contents.contains("alice: logged message"));

    let _ = shutdown_tx.send(());
    server_task.await.expect("server task panicked").unwrap();
    let _ = std::fs::remove_file(&log_path);
}

