//! Profile loading, caching, and the small bits of auth/reporting glue
//! that go with it.

use std::collections::HashMap;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use thiserror::Error;
use tokio::sync::Mutex;
use tokio::time::Instant;

/// A user profile as returned by a [`ProfileBackend`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Profile {
    pub id: String,
    pub name: String,
    pub team: String,
    pub email: String,
}

/// Errors a [`ProfileBackend`] can report when fetching a profile.
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum BackendError {
    #[error("profile not found: {0}")]
    NotFound(String),
    #[error("backend request failed: {0}")]
    Request(String),
}

/// Something that can look up a single profile by id. Implementations
/// talk to whatever actually stores profiles (an HTTP API, a database, etc).
#[allow(async_fn_in_trait)]
pub trait ProfileBackend {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError>;
}

struct CacheEntry {
    profile: Profile,
    inserted_at: Instant,
}

/// Loads profiles through a [`ProfileBackend`], caching results in memory
/// for `ttl` so the team page doesn't hammer the backend on every render.
pub struct ProfileService<B: ProfileBackend> {
    backend: B,
    ttl: Duration,
    cache: Mutex<HashMap<String, CacheEntry>>,
}

impl<B: ProfileBackend> ProfileService<B> {
    pub fn new(backend: B, ttl: Duration) -> Self {
        Self {
            backend,
            ttl,
            cache: Mutex::new(HashMap::new()),
        }
    }

    /// Loads a single profile, serving from cache when the cached entry
    /// hasn't exceeded `ttl` yet.
    pub async fn load(&self, id: &str) -> Result<Profile, BackendError> {
        {
            let cache = self.cache.lock().await;
            if let Some(entry) = cache.get(id) {
                if entry.inserted_at.elapsed() < self.ttl {
                    return Ok(entry.profile.clone());
                }
            }
        }

        let profile = self.backend.fetch(id).await?;

        let mut cache = self.cache.lock().await;
        cache.insert(
            id.to_string(),
            CacheEntry {
                profile: profile.clone(),
                inserted_at: Instant::now(),
            },
        );

        Ok(profile)
    }

    /// Loads a batch of profiles for the team page, one at a time, using
    /// (and populating) the same cache as [`ProfileService::load`].
    pub async fn load_many(&self, ids: &[String]) -> Vec<Result<Profile, BackendError>> {
        let mut results = Vec::with_capacity(ids.len());
        for id in ids {
            results.push(self.load(id).await);
        }
        results
    }
}

/// Credentials for an OAuth-style API client.
///
/// `Debug` is implemented by hand so `client_secret` and `access_token`
/// never end up in logs via a stray `{:?}`.
#[derive(Clone, PartialEq, Eq)]
pub struct ApiCredentials {
    pub client_id: String,
    pub client_secret: String,
    pub access_token: String,
    /// Unix timestamp (seconds) at which `access_token` expires.
    pub expires_at: u64,
}

impl std::fmt::Debug for ApiCredentials {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ApiCredentials")
            .field("client_id", &self.client_id)
            .field("client_secret", &"[redacted]")
            .field("access_token", &"[redacted]")
            .field("expires_at", &self.expires_at)
            .finish()
    }
}

impl ApiCredentials {
    /// Seconds remaining before `access_token` expires. Negative once the
    /// token has already expired, so callers can tell "expired" from
    /// "expiring soon" instead of both reading as zero.
    pub fn seconds_until_expiry(&self) -> i64 {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock is before the Unix epoch")
            .as_secs() as i64;
        self.expires_at as i64 - now
    }
}

/// A parameterized query: `sql` holds `?`-style placeholders and `params`
/// holds the values to bind, in order. Keep it this way rather than
/// formatting `name_prefix`/`team` into the SQL text — that would let a
/// crafted name or team name (e.g. containing `'`) escape the intended
/// query when the reporting job runs it against SQLite.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProfileSearchQuery {
    pub sql: String,
    pub params: Vec<String>,
}

/// Builds the query the reporting job runs to find profiles on a given
/// team whose name starts with `name_prefix`.
pub fn profile_search_sql(name_prefix: &str, team: &str) -> ProfileSearchQuery {
    ProfileSearchQuery {
        sql: "SELECT id, name, team, email FROM profiles WHERE name LIKE ? AND team = ? ORDER BY name"
            .to_string(),
        params: vec![format!("{}%", name_prefix), team.to_string()],
    }
}

use std::collections::HashMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use relay::profiles::{
    profile_search_sql, ApiCredentials, BackendError, Profile, ProfileBackend, ProfileService,
};

#[derive(Clone)]
struct FakeBackend {
    calls: Arc<AtomicUsize>,
    profiles: Arc<Mutex<HashMap<String, Profile>>>,
}

impl FakeBackend {
    fn new(profiles: Vec<Profile>) -> Self {
        let profiles = profiles.into_iter().map(|p| (p.id.clone(), p)).collect();
        Self {
            calls: Arc::new(AtomicUsize::new(0)),
            profiles: Arc::new(Mutex::new(profiles)),
        }
    }

    fn call_count(&self) -> usize {
        self.calls.load(Ordering::SeqCst)
    }
}

impl ProfileBackend for FakeBackend {
    async fn fetch(&self, id: &str) -> Result<Profile, BackendError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.profiles
            .lock()
            .unwrap()
            .get(id)
            .cloned()
            .ok_or_else(|| BackendError::NotFound(id.to_string()))
    }
}

fn sample_profile(id: &str) -> Profile {
    Profile {
        id: id.to_string(),
        name: format!("User {id}"),
        team: "eng".to_string(),
        email: format!("{id}@example.com"),
    }
}

