#[tokio::test(start_paused = true)]
async fn load_refetches_once_ttl_expires() {
    let backend = FakeBackend::new(vec![sample_profile("1")]);
    let handle = backend.clone();
    let service = ProfileService::new(backend, Duration::from_secs(30));

    service.load("1").await.unwrap();
    assert_eq!(handle.call_count(), 1);

    tokio::time::advance(Duration::from_secs(31)).await;

    service.load("1").await.unwrap();
    assert_eq!(handle.call_count(), 2);
}

#[tokio::test]
async fn load_many_fetches_every_id_for_the_team_page() {
    let backend = FakeBackend::new(vec![sample_profile("1"), sample_profile("2")]);
    let service = ProfileService::new(backend, Duration::from_secs(60));

    let ids = vec!["1".to_string(), "2".to_string(), "missing".to_string()];
    let results = service.load_many(&ids).await;

    assert_eq!(results.len(), 3);
    assert_eq!(results[0].as_ref().unwrap().id, "1");
    assert_eq!(results[1].as_ref().unwrap().id, "2");
    assert_eq!(
        results[2].as_ref().unwrap_err(),
        &BackendError::NotFound("missing".to_string())
    );
}

#[tokio::test]
async fn load_many_reuses_the_cache_for_ids_loaded_earlier() {
    let backend = FakeBackend::new(vec![sample_profile("1"), sample_profile("2")]);
    let handle = backend.clone();
    let service = ProfileService::new(backend, Duration::from_secs(60));

    service.load("1").await.unwrap();
    let ids = vec!["1".to_string(), "2".to_string()];
    service.load_many(&ids).await;

    // "1" came from cache, so only "1" (once) and "2" (once) hit the backend.
    assert_eq!(handle.call_count(), 2);
}

#[test]
fn seconds_until_expiry_is_positive_before_expiry() {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let creds = ApiCredentials {
        client_id: "client".to_string(),
        client_secret: "secret".to_string(),
        access_token: "token".to_string(),
        expires_at: now + 120,
    };

    let remaining = creds.seconds_until_expiry();

    assert!(remaining > 0 && remaining <= 120);
}

#[test]
fn seconds_until_expiry_is_negative_once_expired() {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let creds = ApiCredentials {
        client_id: "client".to_string(),
        client_secret: "secret".to_string(),
        access_token: "token".to_string(),
        expires_at: now.saturating_sub(30),
    };

    assert!(creds.seconds_until_expiry() < 0);
}

#[test]
fn debug_format_redacts_credentials() {
    let creds = ApiCredentials {
        client_id: "client-123".to_string(),
        client_secret: "super-secret".to_string(),
        access_token: "abc.def.ghi".to_string(),
        expires_at: 0,
    };

    let debug_output = format!("{creds:?}");

    assert!(debug_output.contains("client-123"));
    assert!(!debug_output.contains("super-secret"));
    assert!(!debug_output.contains("abc.def.ghi"));
}

#[test]
fn profile_search_sql_uses_placeholders_not_string_interpolation() {
    let query = profile_search_sql("O'Brien", "eng'; DROP TABLE profiles; --");

    assert!(query.sql.contains("LIKE ?"));
    assert!(query.sql.contains("team = ?"));
    assert!(!query.sql.contains("O'Brien"));
    assert!(!query.sql.contains("DROP TABLE"));
    assert_eq!(query.params, vec!["O'Brien%", "eng'; DROP TABLE profiles; --"]);
}

"""State sales tax lookup.

Rates are state-level general sales tax rates only (no local add-ons) and are
approximate/illustrative -- verify against an authoritative source (e.g. each
state's department of revenue) before relying on them for real transactions.
"""

import csv
from decimal import ROUND_HALF_UP, Decimal
from pathlib import Path

_RATES_CSV = Path(__file__).resolve().parent / "tax_rates.csv"


def _load_rates() -> dict[str, Decimal]:
    with _RATES_CSV.open(newline="") as f:
        return {row["state"]: Decimal(row["rate"]) for row in csv.DictReader(f)}


_RATES = _load_rates()


def tax_rate(state: str) -> Decimal:
    try:
        return _RATES[state.upper()]
    except KeyError:
        raise ValueError(f"unknown state code: {state!r}") from None


def sales_tax(amount: Decimal, state: str) -> Decimal:
    return (amount * tax_rate(state)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

